------------------------------------------------------------
-- DB 테이블 생성
------------------------------------------------------------

-- 사용자 계정 생성 + 접속권한 설정
Alter session set "_ORACLE_SCRIPT" = true;

------------------------------------------------------------
-- 1. 계정 생성
------------------------------------------------------------

CREATE USER final IDENTIFIED BY 1234;

------------------------------------------------------------
-- 2. 권한 부여
------------------------------------------------------------

GRANT CONNECT, RESOURCE TO final;

------------------------------------------------------------
-- 3. 저장 공간 할당
------------------------------------------------------------

ALTER USER final QUOTA UNLIMITED ON USERS;


------------------------------------------------------------
-- 테이블 삭제
------------------------------------------------------------
DROP TABLE EVENT_STATUS CASCADE CONSTRAINTS;
DROP TABLE EVENT_TRANSFER CASCADE CONSTRAINTS;
DROP TABLE REPLY CASCADE CONSTRAINTS;
DROP TABLE PROCESS_EVENT CASCADE CONSTRAINTS;
DROP TABLE WORK_ASSIGNMENT CASCADE CONSTRAINTS;
DROP TABLE COMPLAINT_WORK CASCADE CONSTRAINTS;
DROP TABLE ATTACHMENT CASCADE CONSTRAINTS;
DROP TABLE COMPLAINT CASCADE CONSTRAINTS;
DROP TABLE OFFICER_ROLE CASCADE CONSTRAINTS;
DROP TABLE OFFICER CASCADE CONSTRAINTS;
DROP TABLE USER_INFO CASCADE CONSTRAINTS;
DROP TABLE COMMON_CODE CASCADE CONSTRAINTS;
DROP TABLE COMMON_CODE_GROUP CASCADE CONSTRAINTS;
DROP TABLE EVENT_TYPE CASCADE CONSTRAINTS;
DROP TABLE STATUS CASCADE CONSTRAINTS;
DROP TABLE DEPARTMENT CASCADE CONSTRAINTS;
DROP TABLE ROLE CASCADE CONSTRAINTS;
DROP TABLE GUEST CASCADE CONSTRAINTS;
DROP TABLE ACCOUNT CASCADE CONSTRAINTS;
DROP TABLE COMPLAINT_FREQUENCY CASCADE CONSTRAINTS;

/*
===============================================================================
 민원 처리 시스템 데이터베이스 생성 스크립트 (Oracle)
===============================================================================
 실행 순서
   1. 기본/업무 테이블 생성
   2. 업무 규칙 검증용 트리거 생성
   3. 조회 성능 향상용 인덱스 생성
   4. 권한, 상태, 이벤트, 공통 코드, 부서의 초기 데이터 등록

 주의
   - Oracle의 IDENTITY, VARCHAR2, CLOB, SYSDATE, PL/SQL 트리거를 사용한다.
   - 비밀번호 컬럼에는 평문이 아닌 해시된 비밀번호를 저장해야 한다.
   - FK 관계 때문에 아래 작성된 순서를 유지하여 실행한다.
===============================================================================
*/

-- ============================================================================
-- 1. 테이블 생성
-- ============================================================================

-- 계정의 로그인 정보와 계정 유형을 관리한다.
-- ACCOUNT_TYPE: 일반 사용자(USER), 공무원(OFFICER)
-- ENABLED: 계정 활성화 여부(Y/N)
CREATE TABLE ACCOUNT (
    ACCOUNT_ID      NUMBER(10)
                    GENERATED BY DEFAULT AS IDENTITY
                    PRIMARY KEY,

    LOGIN_ID        VARCHAR2(30)  NOT NULL,
    PASSWORD        VARCHAR2(255) NOT NULL,
    ACCOUNT_TYPE    VARCHAR2(10)  NOT NULL,
    ENABLED         CHAR(1)       DEFAULT 'Y' NOT NULL,
    CREATED_AT      DATE          DEFAULT SYSDATE NOT NULL,

    CONSTRAINT UK_ACCOUNT_LOGIN_ID
        UNIQUE (LOGIN_ID),

    CONSTRAINT CHK_ACCOUNT_TYPE
        CHECK (ACCOUNT_TYPE IN ('USER', 'OFFICER')),

    CONSTRAINT CHK_ACCOUNT_ENABLED
        CHECK (ENABLED IN ('Y', 'N'))
);

-- 공무원에게 부여할 권한 종류를 관리한다.
-- 예: 시스템 관리자, 부서 관리자, 일반 담당자
CREATE TABLE ROLE (
    ROLE_ID        NUMBER(10)
                   GENERATED BY DEFAULT AS IDENTITY
                   PRIMARY KEY,

    ROLE_CODE      VARCHAR2(30) NOT NULL,
    ROLE_NAME      VARCHAR2(50) NOT NULL,

    CONSTRAINT UK_ROLE_CODE
        UNIQUE (ROLE_CODE),

    CONSTRAINT UK_ROLE_NAME
        UNIQUE (ROLE_NAME)
);

-- 민원 업무의 처리 상태와 화면 표시 순서를 관리한다.
-- DISPLAY_ORDER는 상태를 업무 흐름 순서대로 보여주기 위한 값이다.
CREATE TABLE STATUS (
    STATUS_ID       NUMBER(10)
                    GENERATED BY DEFAULT AS IDENTITY
                    PRIMARY KEY,

    STATUS_CODE     VARCHAR2(30) NOT NULL,
    STATUS_NAME     VARCHAR2(50) NOT NULL,
    DISPLAY_ORDER   NUMBER(3)    NOT NULL,
    ENABLED         CHAR(1)      DEFAULT 'Y' NOT NULL,

    CONSTRAINT UK_STATUS_CODE
        UNIQUE (STATUS_CODE),

    CONSTRAINT UK_STATUS_NAME
        UNIQUE (STATUS_NAME),

    CONSTRAINT UK_STATUS_DISPLAY_ORDER
        UNIQUE (DISPLAY_ORDER),

    CONSTRAINT CHK_STATUS_DISPLAY_ORDER
        CHECK (DISPLAY_ORDER > 0),

    CONSTRAINT CHK_STATUS_ENABLED
        CHECK (ENABLED IN ('Y', 'N'))
);

-- 회원으로 가입한 일반 사용자의 상세 정보를 관리한다.
-- ACCOUNT와 1:1 관계이며 ACCOUNT_ID를 PK이자 FK로 사용한다.
CREATE TABLE USER_INFO (
    ACCOUNT_ID       NUMBER(10)    PRIMARY KEY,
    NAME             VARCHAR2(50)  NOT NULL,
    PHONE            VARCHAR2(20)  NOT NULL,
    EMAIL            VARCHAR2(100) NOT NULL,
    ADDRESS          VARCHAR2(100) NOT NULL,
    ADDRESS_DETAIL   VARCHAR2(100),
    CREATED_AT       DATE          DEFAULT SYSDATE NOT NULL,

    CONSTRAINT UK_USER_INFO_PHONE
        UNIQUE (PHONE),

    CONSTRAINT UK_USER_INFO_EMAIL
        UNIQUE (EMAIL),

    CONSTRAINT FK_USER_INFO_ACCOUNT
        FOREIGN KEY (ACCOUNT_ID)
        REFERENCES ACCOUNT (ACCOUNT_ID)
);

-- 비회원 민원 신청자의 기본 정보를 관리한다.
-- 비회원은 별도 로그인 계정 없이 이름과 휴대전화 번호로 식별한다.
CREATE TABLE GUEST (
    GUEST_ID       NUMBER(10)
                   GENERATED BY DEFAULT AS IDENTITY
                   PRIMARY KEY,

    NAME           VARCHAR2(50) NOT NULL,
    PHONE          VARCHAR2(20) NOT NULL,
    CREATED_AT     DATE         DEFAULT SYSDATE NOT NULL,

    CONSTRAINT UK_GUEST_PHONE
        UNIQUE (PHONE)
);

-- 민원을 처리하는 행정부서의 기본 정보를 관리한다.
-- ENABLED가 N이면 신규 민원 배정 대상에서 제외할 수 있다.
CREATE TABLE DEPARTMENT (
    DEPT_ID       NUMBER(10)
                  GENERATED BY DEFAULT AS IDENTITY
                  PRIMARY KEY,

    DEPT_CODE     VARCHAR2(30)  NOT NULL,
    DEPT_NAME     VARCHAR2(100) NOT NULL,
    ENABLED       CHAR(1)       DEFAULT 'Y' NOT NULL,
    CREATED_AT    DATE          DEFAULT SYSDATE NOT NULL,

    CONSTRAINT UK_DEPARTMENT_CODE
        UNIQUE (DEPT_CODE),

    CONSTRAINT UK_DEPARTMENT_NAME
        UNIQUE (DEPT_NAME),

    CONSTRAINT CHK_DEPARTMENT_ENABLED
        CHECK (ENABLED IN ('Y', 'N'))
);

-- 공무원의 소속 부서와 인적 정보를 관리한다.
-- ACCOUNT와 1:1 관계이며 각 공무원은 하나의 부서에 소속된다.
CREATE TABLE OFFICER (
    ACCOUNT_ID       NUMBER(10)    PRIMARY KEY,
    DEPT_ID          NUMBER(10)    NOT NULL,
    NAME             VARCHAR2(50)  NOT NULL,
    POSITION_NAME    VARCHAR2(30)  NOT NULL,
    PHONE            VARCHAR2(20)  NOT NULL,
    EMAIL            VARCHAR2(100) NOT NULL,
    CREATED_AT       DATE          DEFAULT SYSDATE NOT NULL,

    CONSTRAINT UK_OFFICER_PHONE
        UNIQUE (PHONE),

    CONSTRAINT UK_OFFICER_EMAIL
        UNIQUE (EMAIL),

    CONSTRAINT FK_OFFICER_ACCOUNT
        FOREIGN KEY (ACCOUNT_ID)
        REFERENCES ACCOUNT (ACCOUNT_ID),

    CONSTRAINT FK_OFFICER_DEPARTMENT
        FOREIGN KEY (DEPT_ID)
        REFERENCES DEPARTMENT (DEPT_ID)
);

-- 공무원과 권한 간의 다대다 관계를 관리하는 연결 테이블이다.
-- 복합 PK를 사용하여 동일 권한이 중복 부여되는 것을 방지한다.
CREATE TABLE OFFICER_ROLE (
    ACCOUNT_ID    NUMBER(10) NOT NULL,
    ROLE_ID       NUMBER(10) NOT NULL,

    CONSTRAINT PK_OFFICER_ROLE
        PRIMARY KEY (ACCOUNT_ID, ROLE_ID),

    CONSTRAINT FK_OFFICER_ROLE_OFFICER
        FOREIGN KEY (ACCOUNT_ID)
        REFERENCES OFFICER (ACCOUNT_ID),

    CONSTRAINT FK_OFFICER_ROLE_ROLE
        FOREIGN KEY (ROLE_ID)
        REFERENCES ROLE (ROLE_ID)
);

-- 민원 처리 과정에서 기록할 이벤트의 종류를 관리한다.
-- DEFAULT_PUBLIC_YN은 해당 이벤트를 민원인에게 기본 공개할지 나타낸다.
CREATE TABLE EVENT_TYPE (
    EVENT_TYPE_ID       NUMBER(10)
                        GENERATED BY DEFAULT AS IDENTITY
                        PRIMARY KEY,

    EVENT_CODE          VARCHAR2(30) NOT NULL,
    EVENT_NAME          VARCHAR2(50) NOT NULL,
    DEFAULT_PUBLIC_YN   CHAR(1)      DEFAULT 'Y' NOT NULL,
    DISPLAY_ORDER       NUMBER(5)    DEFAULT 0 NOT NULL,
    ENABLED             CHAR(1)      DEFAULT 'Y' NOT NULL,
    CREATED_AT          DATE         DEFAULT SYSDATE NOT NULL,

    CONSTRAINT UK_EVENT_TYPE_CODE
        UNIQUE (EVENT_CODE),

    CONSTRAINT UK_EVENT_TYPE_NAME
        UNIQUE (EVENT_NAME),

    CONSTRAINT CHK_EVENT_TYPE_PUBLIC
        CHECK (DEFAULT_PUBLIC_YN IN ('Y', 'N')),

    CONSTRAINT CHK_EVENT_TYPE_ENABLED
        CHECK (ENABLED IN ('Y', 'N')),

    CONSTRAINT CHK_EVENT_TYPE_ORDER
        CHECK (DISPLAY_ORDER >= 0)
);

-- 업무 결과, 배정 사유 등 공통 코드의 상위 그룹을 관리한다.
CREATE TABLE COMMON_CODE_GROUP (
    CODE_GROUP_ID   NUMBER(10)
                    GENERATED BY DEFAULT AS IDENTITY
                    PRIMARY KEY,

    GROUP_CODE      VARCHAR2(30)  NOT NULL,
    GROUP_NAME      VARCHAR2(50)  NOT NULL,
    DESCRIPTION     VARCHAR2(500),
    ENABLED         CHAR(1)       DEFAULT 'Y' NOT NULL,
    CREATED_AT      DATE          DEFAULT SYSDATE NOT NULL,

    CONSTRAINT UK_CODE_GROUP_CODE
        UNIQUE (GROUP_CODE),

    CONSTRAINT UK_CODE_GROUP_NAME
        UNIQUE (GROUP_NAME),

    CONSTRAINT CHK_CODE_GROUP_ENABLED
        CHECK (ENABLED IN ('Y', 'N'))
);

-- 공통 코드 그룹에 속하는 실제 코드 값을 관리한다.
-- 같은 그룹 안에서는 CODE_VALUE가 중복될 수 없다.
CREATE TABLE COMMON_CODE (
    COMMON_CODE_ID  NUMBER(10)
                    GENERATED BY DEFAULT AS IDENTITY
                    PRIMARY KEY,

    CODE_GROUP_ID   NUMBER(10)   NOT NULL,
    CODE_VALUE      VARCHAR2(30) NOT NULL,
    CODE_NAME       VARCHAR2(50) NOT NULL,
    DESCRIPTION     VARCHAR2(500),
    DISPLAY_ORDER   NUMBER(5)    DEFAULT 0 NOT NULL,
    ENABLED         CHAR(1)      DEFAULT 'Y' NOT NULL,
    CREATED_AT      DATE         DEFAULT SYSDATE NOT NULL,

    CONSTRAINT FK_COMMON_CODE_GROUP
        FOREIGN KEY (CODE_GROUP_ID)
        REFERENCES COMMON_CODE_GROUP (CODE_GROUP_ID),

    CONSTRAINT UK_COMMON_CODE_VALUE
        UNIQUE (CODE_GROUP_ID, CODE_VALUE),

    CONSTRAINT CHK_COMMON_CODE_ORDER
        CHECK (DISPLAY_ORDER >= 0),

    CONSTRAINT CHK_COMMON_CODE_ENABLED
        CHECK (ENABLED IN ('Y', 'N'))
);

-- 회원 또는 비회원이 신청한 원본 민원을 저장한다.
-- REFINED_CONTENT에는 비속어 처리 및 비표준어 변환 후 내용을 저장할 수 있다.
-- 회원 민원은 ACCOUNT_ID만, 비회원 민원은 GUEST_ID와 PASSWORD를 사용한다.
CREATE TABLE COMPLAINT (
    COMPLAINT_ID      NUMBER(10)
                      GENERATED BY DEFAULT AS IDENTITY
                      PRIMARY KEY,

    ACCOUNT_ID        NUMBER(10),
    GUEST_ID          NUMBER(10),
    TITLE             VARCHAR2(200) NOT NULL,
    PASSWORD          VARCHAR2(255),
    CONTENT           CLOB          NOT NULL,
    REFINED_CONTENT   CLOB,
    IS_PUBLIC         CHAR(1)       DEFAULT 'N' NOT NULL,
    CREATED_AT        DATE          DEFAULT SYSDATE NOT NULL,

    CONSTRAINT FK_COMPLAINT_USER
        FOREIGN KEY (ACCOUNT_ID)
        REFERENCES USER_INFO (ACCOUNT_ID),

    CONSTRAINT FK_COMPLAINT_GUEST
        FOREIGN KEY (GUEST_ID)
        REFERENCES GUEST (GUEST_ID),

    -- 작성자는 회원과 비회원 중 정확히 한 종류만 지정되어야 한다.
    CONSTRAINT CHK_COMPLAINT_WRITER
        CHECK (
            (ACCOUNT_ID IS NOT NULL AND GUEST_ID IS NULL)
            OR
            (ACCOUNT_ID IS NULL AND GUEST_ID IS NOT NULL)
        ),

    -- 회원은 별도 조회 비밀번호를 사용하지 않고, 비회원만 비밀번호를 사용한다.
    CONSTRAINT CHK_COMPLAINT_PASSWORD
        CHECK (
            (
                ACCOUNT_ID IS NOT NULL
                AND GUEST_ID IS NULL
                AND PASSWORD IS NULL
            )
            OR
            (
                ACCOUNT_ID IS NULL
                AND GUEST_ID IS NOT NULL
                AND PASSWORD IS NOT NULL
            )
        ),

    CONSTRAINT CHK_COMPLAINT_PUBLIC
        CHECK (IS_PUBLIC IN ('Y', 'N'))
);

-- 원본 민원을 실제 부서가 처리하는 업무 단위로 분리하여 관리한다.
-- 하나의 민원이 여러 부서에 배정되면 여러 업무가 생성될 수 있다.
-- 이관된 후속 업무는 PARENT_WORK_ID로 이전 업무와 연결한다.
CREATE TABLE COMPLAINT_WORK (
    WORK_ID                  NUMBER(10)
                             GENERATED BY DEFAULT AS IDENTITY
                             PRIMARY KEY,

    COMPLAINT_ID             NUMBER(10) NOT NULL,
    PARENT_WORK_ID           NUMBER(10),
    DEPT_ID                  NUMBER(10) NOT NULL,
    ACCOUNT_ID               NUMBER(10),
    STATUS_ID                NUMBER(10) NOT NULL,
    WORK_RESULT_CODE_ID      NUMBER(10),
    WORK_SEQUENCE            NUMBER(5)  NOT NULL,
    STARTED_AT               DATE       DEFAULT SYSDATE NOT NULL,
    DUE_AT                   DATE,
    ENDED_AT                 DATE,
    CREATED_BY_ACCOUNT_ID    NUMBER(10),
    ENABLED                  CHAR(1)    DEFAULT 'Y' NOT NULL,
    CREATED_AT               DATE       DEFAULT SYSDATE NOT NULL,
    UPDATED_AT               DATE       DEFAULT SYSDATE NOT NULL,

    CONSTRAINT FK_WORK_COMPLAINT
        FOREIGN KEY (COMPLAINT_ID)
        REFERENCES COMPLAINT (COMPLAINT_ID),

    CONSTRAINT FK_WORK_PARENT
        FOREIGN KEY (PARENT_WORK_ID)
        REFERENCES COMPLAINT_WORK (WORK_ID),

    CONSTRAINT FK_WORK_DEPARTMENT
        FOREIGN KEY (DEPT_ID)
        REFERENCES DEPARTMENT (DEPT_ID),

    CONSTRAINT FK_WORK_OFFICER
        FOREIGN KEY (ACCOUNT_ID)
        REFERENCES OFFICER (ACCOUNT_ID),

    CONSTRAINT FK_WORK_STATUS
        FOREIGN KEY (STATUS_ID)
        REFERENCES STATUS (STATUS_ID),

    CONSTRAINT FK_WORK_RESULT_CODE
        FOREIGN KEY (WORK_RESULT_CODE_ID)
        REFERENCES COMMON_CODE (COMMON_CODE_ID),

    CONSTRAINT FK_WORK_CREATED_BY
        FOREIGN KEY (CREATED_BY_ACCOUNT_ID)
        REFERENCES ACCOUNT (ACCOUNT_ID),

    -- 동일 민원 안에서 업무 처리 순번은 중복될 수 없다.
    CONSTRAINT UK_WORK_COMPLAINT_SEQUENCE
        UNIQUE (COMPLAINT_ID, WORK_SEQUENCE),

    CONSTRAINT CHK_WORK_SEQUENCE
        CHECK (WORK_SEQUENCE > 0),

    -- 자기 자신을 이전 업무로 지정하는 잘못된 순환 참조를 방지한다.
    CONSTRAINT CHK_WORK_NOT_SELF_PARENT
        CHECK (
            PARENT_WORK_ID IS NULL
            OR PARENT_WORK_ID <> WORK_ID
        ),

    CONSTRAINT CHK_WORK_DUE_AT
        CHECK (
            DUE_AT IS NULL
            OR DUE_AT >= STARTED_AT
        ),

    CONSTRAINT CHK_WORK_ENDED_AT
        CHECK (
            ENDED_AT IS NULL
            OR ENDED_AT >= STARTED_AT
        ),

    -- 업무 종료 시각과 업무 결과 코드는 항상 함께 입력되거나 함께 비어 있어야 한다.
    CONSTRAINT CHK_WORK_RESULT_ENDED
        CHECK (
            (
                ENDED_AT IS NULL
                AND WORK_RESULT_CODE_ID IS NULL
            )
            OR
            (
                ENDED_AT IS NOT NULL
                AND WORK_RESULT_CODE_ID IS NOT NULL
            )
        ),

    CONSTRAINT CHK_WORK_ENABLED
        CHECK (ENABLED IN ('Y', 'N'))
);

-- 민원 업무의 담당자 배정 및 해제 이력을 관리한다.
-- 현재 담당 배정은 UNASSIGNED_AT이 NULL인 행으로 판단한다.
CREATE TABLE WORK_ASSIGNMENT (
    ASSIGNMENT_ID             NUMBER(10)
                              GENERATED BY DEFAULT AS IDENTITY
                              PRIMARY KEY,

    WORK_ID                   NUMBER(10) NOT NULL,
    ACCOUNT_ID                NUMBER(10) NOT NULL,
    ASSIGNED_BY_ACCOUNT_ID    NUMBER(10) NOT NULL,
    ASSIGN_REASON_CODE_ID     NUMBER(10) NOT NULL,
    ASSIGNED_AT               DATE       DEFAULT SYSDATE NOT NULL,
    UNASSIGNED_AT             DATE,
    UNASSIGN_REASON_CODE_ID   NUMBER(10),
    MEMO                      VARCHAR2(500),

    CONSTRAINT FK_ASSIGNMENT_WORK
        FOREIGN KEY (WORK_ID)
        REFERENCES COMPLAINT_WORK (WORK_ID),

    CONSTRAINT FK_ASSIGNMENT_OFFICER
        FOREIGN KEY (ACCOUNT_ID)
        REFERENCES OFFICER (ACCOUNT_ID),

    CONSTRAINT FK_ASSIGNMENT_ASSIGNED_BY
        FOREIGN KEY (ASSIGNED_BY_ACCOUNT_ID)
        REFERENCES ACCOUNT (ACCOUNT_ID),

    CONSTRAINT FK_ASSIGNMENT_REASON
        FOREIGN KEY (ASSIGN_REASON_CODE_ID)
        REFERENCES COMMON_CODE (COMMON_CODE_ID),

    CONSTRAINT FK_UNASSIGN_REASON
        FOREIGN KEY (UNASSIGN_REASON_CODE_ID)
        REFERENCES COMMON_CODE (COMMON_CODE_ID),

    CONSTRAINT CHK_ASSIGNMENT_UNASSIGNED_AT
        CHECK (
            UNASSIGNED_AT IS NULL
            OR UNASSIGNED_AT >= ASSIGNED_AT
        ),

    -- 담당 해제 시각과 해제 사유는 항상 함께 입력되어야 한다.
    CONSTRAINT CHK_ASSIGNMENT_UNASSIGN_REASON
        CHECK (
            (
                UNASSIGNED_AT IS NULL
                AND UNASSIGN_REASON_CODE_ID IS NULL
            )
            OR
            (
                UNASSIGNED_AT IS NOT NULL
                AND UNASSIGN_REASON_CODE_ID IS NOT NULL
            )
        )
);

-- 업무 생성, 담당자 변경, 상태 변경, 부서 이관 등의 처리 이력을 기록한다.
-- EVENT_SEQUENCE로 같은 업무의 이벤트 순서를 보장한다.
CREATE TABLE PROCESS_EVENT (
    EVENT_ID         NUMBER(10)
                     GENERATED BY DEFAULT AS IDENTITY
                     PRIMARY KEY,

    WORK_ID          NUMBER(10)    NOT NULL,
    EVENT_TYPE_ID    NUMBER(10)    NOT NULL,
    ACCOUNT_ID       NUMBER(10),
    EVENT_SEQUENCE   NUMBER(10)    NOT NULL,
    EVENT_TIME       DATE          DEFAULT SYSDATE NOT NULL,
    PUBLIC_YN        CHAR(1)       DEFAULT 'Y' NOT NULL,
    EVENT_COMMENT    VARCHAR2(1000),
    CREATED_AT       DATE          DEFAULT SYSDATE NOT NULL,

    CONSTRAINT FK_EVENT_WORK
        FOREIGN KEY (WORK_ID)
        REFERENCES COMPLAINT_WORK (WORK_ID),

    CONSTRAINT FK_EVENT_TYPE
        FOREIGN KEY (EVENT_TYPE_ID)
        REFERENCES EVENT_TYPE (EVENT_TYPE_ID),

    CONSTRAINT FK_EVENT_ACCOUNT
        FOREIGN KEY (ACCOUNT_ID)
        REFERENCES ACCOUNT (ACCOUNT_ID),

    CONSTRAINT UK_EVENT_WORK_SEQUENCE
        UNIQUE (WORK_ID, EVENT_SEQUENCE),

    CONSTRAINT CHK_EVENT_SEQUENCE
        CHECK (EVENT_SEQUENCE > 0),

    CONSTRAINT CHK_EVENT_PUBLIC_YN
        CHECK (PUBLIC_YN IN ('Y', 'N'))
);

-- 상태 변경 이벤트의 변경 전/후 상태를 저장한다.
-- PROCESS_EVENT와 1:1 관계이며 원본 이벤트 삭제 시 함께 삭제된다.
CREATE TABLE EVENT_STATUS (
    EVENT_ID          NUMBER(10) PRIMARY KEY,
    BEFORE_STATUS_ID  NUMBER(10),
    AFTER_STATUS_ID   NUMBER(10) NOT NULL,
    STATUS_REASON     VARCHAR2(500),

    CONSTRAINT FK_EVENT_STATUS_EVENT
        FOREIGN KEY (EVENT_ID)
        REFERENCES PROCESS_EVENT (EVENT_ID)
        ON DELETE CASCADE,

    CONSTRAINT FK_EVENT_STATUS_BEFORE
        FOREIGN KEY (BEFORE_STATUS_ID)
        REFERENCES STATUS (STATUS_ID),

    CONSTRAINT FK_EVENT_STATUS_AFTER
        FOREIGN KEY (AFTER_STATUS_ID)
        REFERENCES STATUS (STATUS_ID),

    CONSTRAINT CHK_EVENT_STATUS_DIFFERENT
        CHECK (
            BEFORE_STATUS_ID IS NULL
            OR BEFORE_STATUS_ID <> AFTER_STATUS_ID
        )
);

-- 부서 이관 이벤트의 출발 부서, 도착 부서, 이관 사유를 저장한다.
-- NEW_WORK_ID는 이관으로 새로 생성된 후속 업무를 가리킨다.
CREATE TABLE EVENT_TRANSFER (
    EVENT_ID                   NUMBER(10) PRIMARY KEY,
    FROM_DEPT_ID               NUMBER(10) NOT NULL,
    TO_DEPT_ID                 NUMBER(10) NOT NULL,
    TRANSFER_REASON_CODE_ID    NUMBER(10) NOT NULL,
    TRANSFER_REASON_DETAIL     VARCHAR2(500),
    NEW_WORK_ID                NUMBER(10) NOT NULL,

    CONSTRAINT FK_EVENT_TRANSFER_EVENT
        FOREIGN KEY (EVENT_ID)
        REFERENCES PROCESS_EVENT (EVENT_ID)
        ON DELETE CASCADE,

    CONSTRAINT FK_EVENT_TRANSFER_FROM
        FOREIGN KEY (FROM_DEPT_ID)
        REFERENCES DEPARTMENT (DEPT_ID),

    CONSTRAINT FK_EVENT_TRANSFER_TO
        FOREIGN KEY (TO_DEPT_ID)
        REFERENCES DEPARTMENT (DEPT_ID),

    CONSTRAINT FK_EVENT_TRANSFER_REASON
        FOREIGN KEY (TRANSFER_REASON_CODE_ID)
        REFERENCES COMMON_CODE (COMMON_CODE_ID),

    CONSTRAINT FK_EVENT_TRANSFER_NEW_WORK
        FOREIGN KEY (NEW_WORK_ID)
        REFERENCES COMPLAINT_WORK (WORK_ID),

    CONSTRAINT UK_EVENT_TRANSFER_NEW_WORK
        UNIQUE (NEW_WORK_ID),

    CONSTRAINT CHK_EVENT_TRANSFER_DIFFERENT
        CHECK (FROM_DEPT_ID <> TO_DEPT_ID)
);

-- 민원 신청 시 업로드한 첨부파일의 메타데이터를 관리한다.
-- 실제 파일 데이터가 아니라 저장 경로, 파일명, 크기 등을 저장한다.
CREATE TABLE ATTACHMENT (
    FILE_ID          NUMBER(10)
                     GENERATED BY DEFAULT AS IDENTITY
                     PRIMARY KEY,

    COMPLAINT_ID     NUMBER(10)    NOT NULL,
    ORIGINAL_NAME    VARCHAR2(255) NOT NULL,
    STORED_NAME      VARCHAR2(255) NOT NULL,
    FILE_PATH        VARCHAR2(500) NOT NULL,
    FILE_SIZE        NUMBER(20)    NOT NULL,
    CREATED_AT       DATE          DEFAULT SYSDATE NOT NULL,

    CONSTRAINT FK_ATTACHMENT_COMPLAINT
        FOREIGN KEY (COMPLAINT_ID)
        REFERENCES COMPLAINT (COMPLAINT_ID),

    CONSTRAINT CHK_ATTACHMENT_FILE_SIZE
        CHECK (FILE_SIZE >= 0)
);

-- 담당 공무원이 작성한 민원 답변을 관리한다.
-- UK_REPLY_WORK 제약으로 하나의 업무에는 하나의 최종 답변만 등록한다.
CREATE TABLE REPLY (
    REPLY_ID        NUMBER(10)
                    GENERATED BY DEFAULT AS IDENTITY
                    PRIMARY KEY,

    WORK_ID         NUMBER(10)    NOT NULL,
    ACCOUNT_ID      NUMBER(10)    NOT NULL,
    TITLE           VARCHAR2(200) NOT NULL,
    CONTENT         CLOB          NOT NULL,
    CREATED_AT      DATE          DEFAULT SYSDATE NOT NULL,
    UPDATED_AT      DATE          DEFAULT SYSDATE NOT NULL,

    CONSTRAINT UK_REPLY_WORK
        UNIQUE (WORK_ID),

    CONSTRAINT FK_REPLY_WORK
        FOREIGN KEY (WORK_ID)
        REFERENCES COMPLAINT_WORK (WORK_ID),

    CONSTRAINT FK_REPLY_OFFICER
        FOREIGN KEY (ACCOUNT_ID)
        REFERENCES OFFICER (ACCOUNT_ID)
);

-- 자주 찾는 민원(FAQ)의 질문과 답변을 관리한다.
CREATE TABLE COMPLAINT_FREQUENCY (
    FAQ_ID          NUMBER(10)
                    GENERATED BY DEFAULT AS IDENTITY
                    PRIMARY KEY,

    QUESTION        VARCHAR2(500) NOT NULL,
    ANSWER          CLOB          NOT NULL,
    DISPLAY_ORDER   NUMBER(5),
    ENABLED         CHAR(1)       DEFAULT 'Y' NOT NULL,
    CREATED_AT      DATE          DEFAULT SYSDATE NOT NULL,

    CONSTRAINT CHK_FAQ_ENABLED
        CHECK (ENABLED IN ('Y', 'N')),

    CONSTRAINT CHK_FAQ_DISPLAY_ORDER
        CHECK (
            DISPLAY_ORDER IS NULL
            OR DISPLAY_ORDER > 0
        )
);

-- ============================================================================
-- 2. 업무 규칙 검증 및 자동 갱신 트리거
-- ============================================================================

-- USER_INFO에 연결되는 계정이 실제로 USER 유형인지 검사한다.
-- 잘못된 계정 유형 또는 존재하지 않는 계정이면 등록을 중단한다.
CREATE OR REPLACE TRIGGER TRG_USER_INFO_ACCOUNT_CHECK
BEFORE INSERT OR UPDATE OF ACCOUNT_ID
ON USER_INFO
FOR EACH ROW
DECLARE
    V_ACCOUNT_TYPE ACCOUNT.ACCOUNT_TYPE%TYPE;
BEGIN
    SELECT ACCOUNT_TYPE
      INTO V_ACCOUNT_TYPE
      FROM ACCOUNT
     WHERE ACCOUNT_ID = :NEW.ACCOUNT_ID;

    IF V_ACCOUNT_TYPE <> 'USER' THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            'USER_INFO에는 USER 계정만 등록할 수 있습니다.'
        );
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(
            -20002,
            '존재하지 않는 계정입니다.'
        );
END;
/

-- OFFICER에 연결되는 계정이 실제로 OFFICER 유형인지 검사한다.
CREATE OR REPLACE TRIGGER TRG_OFFICER_ACCOUNT_CHECK
BEFORE INSERT OR UPDATE OF ACCOUNT_ID
ON OFFICER
FOR EACH ROW
DECLARE
    V_ACCOUNT_TYPE ACCOUNT.ACCOUNT_TYPE%TYPE;
BEGIN
    SELECT ACCOUNT_TYPE
      INTO V_ACCOUNT_TYPE
      FROM ACCOUNT
     WHERE ACCOUNT_ID = :NEW.ACCOUNT_ID;

    IF V_ACCOUNT_TYPE <> 'OFFICER' THEN
        RAISE_APPLICATION_ERROR(
            -20003,
            'OFFICER에는 OFFICER 계정만 등록할 수 있습니다.'
        );
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(
            -20004,
            '존재하지 않는 계정입니다.'
        );
END;
/

-- 계정 생성 후 USER와 OFFICER 유형을 서로 변경하지 못하게 한다.
-- 유형별 상세 테이블과의 데이터 불일치를 방지하기 위한 트리거이다.
CREATE OR REPLACE TRIGGER TRG_ACCOUNT_TYPE_IMMUTABLE
BEFORE UPDATE OF ACCOUNT_TYPE
ON ACCOUNT
FOR EACH ROW
BEGIN
    IF :OLD.ACCOUNT_TYPE <> :NEW.ACCOUNT_TYPE THEN
        RAISE_APPLICATION_ERROR(
            -20005,
            'ACCOUNT_TYPE은 계정 생성 후 변경할 수 없습니다.'
        );
    END IF;
END;
/

-- 민원 업무가 수정될 때 UPDATED_AT을 현재 시각으로 자동 변경한다.
CREATE OR REPLACE TRIGGER TRG_WORK_UPDATED_AT
BEFORE UPDATE
ON COMPLAINT_WORK
FOR EACH ROW
BEGIN
    :NEW.UPDATED_AT := SYSDATE;
END;
/

-- 답변이 수정될 때 UPDATED_AT을 현재 시각으로 자동 변경한다.
CREATE OR REPLACE TRIGGER TRG_REPLY_UPDATED_AT
BEFORE UPDATE
ON REPLY
FOR EACH ROW
BEGIN
    :NEW.UPDATED_AT := SYSDATE;
END;
/

-- 한 원본 민원에 생성할 수 있는 최초 부서 업무를 최대 3개로 제한한다.
-- 행 단위 처리 후 전체 결과를 검사해야 하므로 COMPOUND TRIGGER를 사용한다.
CREATE OR REPLACE TRIGGER TRG_WORK_INITIAL_MAX_3
FOR INSERT OR UPDATE OF COMPLAINT_ID, PARENT_WORK_ID
ON COMPLAINT_WORK
COMPOUND TRIGGER

    AFTER STATEMENT IS
        V_OVER_COUNT NUMBER;
    BEGIN
        SELECT COUNT(*)
          INTO V_OVER_COUNT
          FROM (
                SELECT COMPLAINT_ID
                  FROM COMPLAINT_WORK
                 WHERE PARENT_WORK_ID IS NULL
                 GROUP BY COMPLAINT_ID
                HAVING COUNT(*) > 3
          );

        IF V_OVER_COUNT > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20010,
                '하나의 원본 민원에는 최초 부서 업무를 최대 3개까지만 생성할 수 있습니다.'
            );
        END IF;
    END AFTER STATEMENT;

END;
/

-- 후속 업무의 부모 업무가 존재하는지 확인하고,
-- 부모와 자식 업무가 동일한 원본 민원에 속하는지 검사한다.
CREATE OR REPLACE TRIGGER TRG_WORK_PARENT_CHECK
AFTER INSERT OR UPDATE OF COMPLAINT_ID, PARENT_WORK_ID
ON COMPLAINT_WORK
DECLARE
      V_MISSING_PARENT_COUNT NUMBER;
      V_INVALID_PARENT_COUNT NUMBER;
BEGIN

    -- 존재하지 않는 업무 ID를 부모로 지정한 행이 있는지 검사한다.
    SELECT COUNT(*)
        INTO V_MISSING_PARENT_COUNT
        FROM COMPLAINT_WORK CHILD
       WHERE CHILD.PARENT_WORK_ID IS NOT NULL
         AND NOT EXISTS (
             SELECT 1
               FROM COMPLAINT_WORK PARENT
              WHERE PARENT.WORK_ID = CHILD.PARENT_WORK_ID
         );

    IF V_MISSING_PARENT_COUNT > 0 THEN
          RAISE_APPLICATION_ERROR(
              -20012,
              '이전 업무가 존재하지 않습니다.'
          );
    END IF;

    -- 부모 업무와 후속 업무의 원본 민원이 서로 다른지 검사한다.
    SELECT COUNT(*)
        INTO V_INVALID_PARENT_COUNT
        FROM COMPLAINT_WORK CHILD
        JOIN COMPLAINT_WORK PARENT
          ON PARENT.WORK_ID = CHILD.PARENT_WORK_ID
       WHERE CHILD.PARENT_WORK_ID IS NOT NULL
         AND CHILD.COMPLAINT_ID <> PARENT.COMPLAINT_ID;

    IF V_INVALID_PARENT_COUNT > 0 THEN
          RAISE_APPLICATION_ERROR(
              -20011,
              '이관 후속 업무는 이전 업무와 동일한 원본 민원에 속해야 합니다.'
          );
    END IF;
END;
/

-- 담당자를 배정할 때 다음 두 업무 규칙을 검사한다.
--   1) 담당자는 해당 업무의 부서에 소속되어야 한다.
--   2) 배정 수행자는 MANAGER 또는 ADMIN 권한을 가져야 한다.
CREATE OR REPLACE TRIGGER TRG_WORK_ASSIGNMENT_CHECK
BEFORE INSERT
ON WORK_ASSIGNMENT
FOR EACH ROW
DECLARE
    V_WORK_DEPT_ID       COMPLAINT_WORK.DEPT_ID%TYPE;
    V_OFFICER_DEPT_ID    OFFICER.DEPT_ID%TYPE;
    V_MANAGER_ROLE_COUNT NUMBER;
BEGIN
    -- 배정할 업무의 부서와 담당 공무원의 소속 부서를 조회한다.
    SELECT DEPT_ID
      INTO V_WORK_DEPT_ID
      FROM COMPLAINT_WORK
     WHERE WORK_ID = :NEW.WORK_ID;

    SELECT DEPT_ID
      INTO V_OFFICER_DEPT_ID
      FROM OFFICER
     WHERE ACCOUNT_ID = :NEW.ACCOUNT_ID;

    IF V_WORK_DEPT_ID <> V_OFFICER_DEPT_ID THEN
        RAISE_APPLICATION_ERROR(
            -20020,
            '업무 담당자는 해당 업무 부서 소속이어야 합니다.'
        );
    END IF;

    -- 배정을 수행한 계정의 관리자 권한 보유 여부를 확인한다.
    SELECT COUNT(*)
      INTO V_MANAGER_ROLE_COUNT
      FROM OFFICER_ROLE ORL
      JOIN ROLE R
        ON R.ROLE_ID = ORL.ROLE_ID
     WHERE ORL.ACCOUNT_ID = :NEW.ASSIGNED_BY_ACCOUNT_ID
       AND R.ROLE_CODE IN ('MANAGER', 'ADMIN');

    IF V_MANAGER_ROLE_COUNT = 0 THEN
        RAISE_APPLICATION_ERROR(
            -20021,
            '담당자 배정은 MANAGER 또는 ADMIN 권한이 필요합니다.'
        );
    END IF;
END;
/

-- 부서 이관 상세 정보가 실제 이벤트 및 전후 업무와 일치하는지 검사한다.
-- 이벤트 유형, 출발/도착 부서, 부모 업무, 원본 민원까지 교차 검증한다.
CREATE OR REPLACE TRIGGER TRG_EVENT_TRANSFER_CHECK
BEFORE INSERT OR UPDATE
ON EVENT_TRANSFER
FOR EACH ROW
DECLARE
    V_OLD_WORK_ID          PROCESS_EVENT.WORK_ID%TYPE;
    V_OLD_COMPLAINT_ID     COMPLAINT_WORK.COMPLAINT_ID%TYPE;
    V_OLD_DEPT_ID          COMPLAINT_WORK.DEPT_ID%TYPE;

    V_NEW_COMPLAINT_ID     COMPLAINT_WORK.COMPLAINT_ID%TYPE;
    V_NEW_DEPT_ID          COMPLAINT_WORK.DEPT_ID%TYPE;
    V_NEW_PARENT_WORK_ID   COMPLAINT_WORK.PARENT_WORK_ID%TYPE;

    V_EVENT_CODE           EVENT_TYPE.EVENT_CODE%TYPE;
BEGIN
    -- 이관 이벤트가 연결된 기존 업무와 이벤트 유형을 조회한다.
    SELECT PE.WORK_ID,
           ET.EVENT_CODE
      INTO V_OLD_WORK_ID,
           V_EVENT_CODE
      FROM PROCESS_EVENT PE
      JOIN EVENT_TYPE ET
        ON ET.EVENT_TYPE_ID = PE.EVENT_TYPE_ID
     WHERE PE.EVENT_ID = :NEW.EVENT_ID;

    IF V_EVENT_CODE <> 'DEPARTMENT_TRANSFERRED' THEN
        RAISE_APPLICATION_ERROR(
            -20030,
            'EVENT_TRANSFER는 부서 이관 이벤트에만 등록할 수 있습니다.'
        );
    END IF;

    -- 이관 전 업무의 원본 민원과 담당 부서를 조회한다.
    SELECT COMPLAINT_ID,
           DEPT_ID
      INTO V_OLD_COMPLAINT_ID,
           V_OLD_DEPT_ID
      FROM COMPLAINT_WORK
     WHERE WORK_ID = V_OLD_WORK_ID;

    -- 이관 후 새 업무의 원본 민원, 담당 부서, 부모 업무를 조회한다.
    SELECT COMPLAINT_ID,
           DEPT_ID,
           PARENT_WORK_ID
      INTO V_NEW_COMPLAINT_ID,
           V_NEW_DEPT_ID,
           V_NEW_PARENT_WORK_ID
      FROM COMPLAINT_WORK
     WHERE WORK_ID = :NEW.NEW_WORK_ID;

    IF V_OLD_DEPT_ID <> :NEW.FROM_DEPT_ID THEN
        RAISE_APPLICATION_ERROR(
            -20031,
            'FROM_DEPT_ID가 이관 전 업무 부서와 일치하지 않습니다.'
        );
    END IF;

    IF V_NEW_DEPT_ID <> :NEW.TO_DEPT_ID THEN
        RAISE_APPLICATION_ERROR(
            -20032,
            'TO_DEPT_ID가 새 업무 부서와 일치하지 않습니다.'
        );
    END IF;

    IF V_NEW_PARENT_WORK_ID <> V_OLD_WORK_ID THEN
        RAISE_APPLICATION_ERROR(
            -20033,
            '새 업무의 PARENT_WORK_ID는 이관 전 업무여야 합니다.'
        );
    END IF;

    IF V_OLD_COMPLAINT_ID <> V_NEW_COMPLAINT_ID THEN
        RAISE_APPLICATION_ERROR(
            -20034,
            '이관 전후 업무는 동일한 원본 민원에 속해야 합니다.'
        );
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(
            -20035,
            '이관 이벤트 또는 이관 전후 업무가 존재하지 않습니다.'
        );
END;
/

-- ============================================================================
-- 3. 조회 성능 향상 및 중복 방지 인덱스
-- ============================================================================

-- 회원별 민원 조회 성능을 높인다.
CREATE INDEX IDX_COMPLAINT_ACCOUNT
    ON COMPLAINT (ACCOUNT_ID);

-- 비회원별 민원 조회 성능을 높인다.
CREATE INDEX IDX_COMPLAINT_GUEST
    ON COMPLAINT (GUEST_ID);

-- 민원 접수일 기준 정렬 및 기간 검색 성능을 높인다.
CREATE INDEX IDX_COMPLAINT_CREATED_AT
    ON COMPLAINT (CREATED_AT);

-- 특정 민원의 첨부파일 목록 조회 성능을 높인다.
CREATE INDEX IDX_ATTACHMENT_COMPLAINT
    ON ATTACHMENT (COMPLAINT_ID);

-- 부서별 공무원 목록 조회 성능을 높인다.
CREATE INDEX IDX_OFFICER_DEPARTMENT
    ON OFFICER (DEPT_ID);

-- 권한별 공무원 조회 성능을 높인다.
CREATE INDEX IDX_OFFICER_ROLE_ROLE
    ON OFFICER_ROLE (ROLE_ID);

-- 코드 그룹별 활성 공통 코드를 화면 표시 순서로 조회할 때 사용한다.
CREATE INDEX IDX_COMMON_CODE_GROUP
    ON COMMON_CODE (
        CODE_GROUP_ID,
        ENABLED,
        DISPLAY_ORDER
    );

-- 부서별·상태별 업무 목록과 접수 순서 조회에 사용한다.
CREATE INDEX IDX_WORK_DEPT_STATUS
    ON COMPLAINT_WORK (
        DEPT_ID,
        STATUS_ID,
        STARTED_AT
    );

-- 담당자별·상태별 업무 목록 조회에 사용한다.
CREATE INDEX IDX_WORK_OFFICER_STATUS
    ON COMPLAINT_WORK (
        ACCOUNT_ID,
        STATUS_ID,
        STARTED_AT
    );

-- 특정 업무에서 이어진 후속 이관 업무를 조회할 때 사용한다.
CREATE INDEX IDX_WORK_PARENT
    ON COMPLAINT_WORK (PARENT_WORK_ID);

-- 처리 기한과 상태를 기준으로 지연 예정 업무를 조회할 때 사용한다.
CREATE INDEX IDX_WORK_DUE
    ON COMPLAINT_WORK (
        DUE_AT,
        STATUS_ID
    );

-- 업무별 담당자 배정 이력을 시간순으로 조회할 때 사용한다.
CREATE INDEX IDX_ASSIGNMENT_WORK_TIME
    ON WORK_ASSIGNMENT (
        WORK_ID,
        ASSIGNED_AT
    );

-- 공무원별 배정 이력을 시간순으로 조회할 때 사용한다.
CREATE INDEX IDX_ASSIGNMENT_OFFICER_TIME
    ON WORK_ASSIGNMENT (
        ACCOUNT_ID,
        ASSIGNED_AT
    );

-- 함수 기반 UNIQUE 인덱스이다.
-- UNASSIGNED_AT이 NULL인 현재 배정 행을 업무당 최대 1개로 제한한다.
CREATE UNIQUE INDEX UK_ASSIGNMENT_CURRENT_ONE
    ON WORK_ASSIGNMENT (
        CASE
            WHEN UNASSIGNED_AT IS NULL
            THEN WORK_ID
        END
    );

-- 업무별 처리 이벤트를 발생 시간과 순번에 따라 조회할 때 사용한다.
CREATE INDEX IDX_EVENT_WORK_TIMELINE
    ON PROCESS_EVENT (
        WORK_ID,
        EVENT_TIME,
        EVENT_SEQUENCE
    );

-- 이벤트 종류별 발생 이력을 시간순으로 조회할 때 사용한다.
CREATE INDEX IDX_EVENT_TYPE_TIME
    ON PROCESS_EVENT (
        EVENT_TYPE_ID,
        EVENT_TIME
    );

-- 계정별 처리 이벤트 이력을 시간순으로 조회할 때 사용한다.
CREATE INDEX IDX_EVENT_ACCOUNT_TIME
    ON PROCESS_EVENT (
        ACCOUNT_ID,
        EVENT_TIME
    );

-- 변경 후 상태를 기준으로 상태 변경 이벤트를 조회할 때 사용한다.
CREATE INDEX IDX_EVENT_STATUS_AFTER
    ON EVENT_STATUS (AFTER_STATUS_ID);

-- 출발 부서 기준 이관 이력 조회에 사용한다.
CREATE INDEX IDX_EVENT_TRANSFER_FROM
    ON EVENT_TRANSFER (FROM_DEPT_ID);

-- 도착 부서 기준 이관 이력 조회에 사용한다.
CREATE INDEX IDX_EVENT_TRANSFER_TO
    ON EVENT_TRANSFER (TO_DEPT_ID);

-- 공무원별 답변 작성 내역 조회에 사용한다.
CREATE INDEX IDX_REPLY_OFFICER
    ON REPLY (ACCOUNT_ID);

