/*
===============================================================================
 민원 처리 시스템 더미데이터 및 업무 흐름 검증 스크립트 (Oracle)
===============================================================================
 주요 구성
   1. 공무원·회원·비회원 계정 생성
   2. 민원과 부서별 처리 업무 생성
   3. 담당자 배정·변경, 상태 변경, 부서 이관, 답변·반려 이력 생성
   4. 사례별 시연 데이터와 업무 규칙 검증 데이터 생성
   5. 데이터 정합성 확인용 SELECT 실행

 주의
   - 앞서 작성한 테이블, 트리거, 권한, 상태, 공통 코드가 먼저 생성되어야 한다.
   - 고정 ACCOUNT_ID와 테스트용 로그인 정보가 포함되어 있으므로 개발/시연 DB에서 사용한다.
   - 비밀번호 값은 평문이 아니라 해시 형식의 테스트 값이다.
   - SQL*Plus 및 SQL Developer에서 & 문자를 치환 변수로 처리하지 않도록 DEFINE을 끈다.
===============================================================================
*/

SET DEFINE OFF;

