-- 모든 최초 업무에 WORK_CREATED 이벤트를 기록한다.
-- ACCOUNT_ID가 NULL인 것은 시스템 또는 AI가 자동 생성한 이벤트임을 의미한다.
INSERT INTO PROCESS_EVENT (
    WORK_ID,
    EVENT_TYPE_ID,
    ACCOUNT_ID,
    EVENT_SEQUENCE,
    PUBLIC_YN,
    EVENT_COMMENT
)
SELECT
    CW.WORK_ID,
    ET.EVENT_TYPE_ID,
    NULL,
    1,
    'Y',
    'AI가 민원 내용을 분석하여 최초 처리 부서를 배정함'
FROM COMPLAINT_WORK CW
  JOIN EVENT_TYPE ET
    ON ET.EVENT_CODE = 'WORK_CREATED'
 WHERE CW.PARENT_WORK_ID IS NULL;

-- ============================================================================
-- 6. 사례 1~8의 담당자 배정 및 상태 변경
-- ============================================================================
-- 반복되는 배정 로직을 ASSIGN_WORK 내부 프로시저로 정의한 뒤 사례별로 호출한다.
DECLARE
    PROCEDURE ASSIGN_WORK (
        P_TITLE       VARCHAR2,
        P_DEPT_CODE   VARCHAR2,
        P_OFFICER_ID  VARCHAR2,
        P_MANAGER_ID  VARCHAR2,
        P_STATUS_CODE VARCHAR2
    ) IS
        V_WORK_ID        NUMBER;
        V_OFFICER_ACC    NUMBER;
        V_MANAGER_ACC    NUMBER;
        V_ASSIGN_CODE    NUMBER;
        V_STATUS_ID      NUMBER;
        V_EVENT_TYPE_ID  NUMBER;
        V_EVENT_ID       NUMBER;
        V_NEXT_SEQ       NUMBER;
        V_OLD_STATUS_ID  NUMBER;
    BEGIN
        SELECT CW.WORK_ID, CW.STATUS_ID
          INTO V_WORK_ID, V_OLD_STATUS_ID
          FROM COMPLAINT_WORK CW
          JOIN COMPLAINT C ON C.COMPLAINT_ID = CW.COMPLAINT_ID
          JOIN DEPARTMENT D ON D.DEPT_ID = CW.DEPT_ID
         WHERE C.TITLE = P_TITLE
           AND D.DEPT_CODE = P_DEPT_CODE
           AND CW.ENDED_AT IS NULL;

        SELECT ACCOUNT_ID INTO V_OFFICER_ACC
          FROM ACCOUNT WHERE LOGIN_ID = P_OFFICER_ID;

        SELECT ACCOUNT_ID INTO V_MANAGER_ACC
          FROM ACCOUNT WHERE LOGIN_ID = P_MANAGER_ID;

        SELECT CC.COMMON_CODE_ID
          INTO V_ASSIGN_CODE
          FROM COMMON_CODE CC
          JOIN COMMON_CODE_GROUP CG
            ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
         WHERE CG.GROUP_CODE = 'ASSIGN_REASON'
           AND CC.CODE_VALUE = 'INITIAL';

        -- 담당자 배정 이력을 먼저 기록한다.
        INSERT INTO WORK_ASSIGNMENT (
            WORK_ID, ACCOUNT_ID, ASSIGNED_BY_ACCOUNT_ID,
            ASSIGN_REASON_CODE_ID, MEMO
        ) VALUES (
            V_WORK_ID, V_OFFICER_ACC, V_MANAGER_ACC,
            V_ASSIGN_CODE, '더미데이터 최초 담당자 배정'
        );

        SELECT STATUS_ID INTO V_STATUS_ID
          FROM STATUS WHERE STATUS_CODE = P_STATUS_CODE;

        -- 현재 담당자와 업무 상태를 실제 업무 행에 반영한다.
        UPDATE COMPLAINT_WORK
           SET ACCOUNT_ID = V_OFFICER_ACC,
               STATUS_ID = V_STATUS_ID
         WHERE WORK_ID = V_WORK_ID;

        SELECT EVENT_TYPE_ID INTO V_EVENT_TYPE_ID
          FROM EVENT_TYPE WHERE EVENT_CODE = 'OFFICER_ASSIGNED';

        SELECT NVL(MAX(EVENT_SEQUENCE), 0) + 1
          INTO V_NEXT_SEQ
          FROM PROCESS_EVENT
         WHERE WORK_ID = V_WORK_ID;

        -- 담당자 배정 이벤트를 업무 타임라인에 추가한다.
        INSERT INTO PROCESS_EVENT (
            WORK_ID,
            EVENT_TYPE_ID,
            ACCOUNT_ID,
            EVENT_SEQUENCE,
            PUBLIC_YN
        ) VALUES (
            V_WORK_ID,
            V_EVENT_TYPE_ID,
            V_MANAGER_ACC,
            V_NEXT_SEQ,
            'Y'
        );

        SELECT EVENT_TYPE_ID INTO V_EVENT_TYPE_ID
          FROM EVENT_TYPE WHERE EVENT_CODE = 'STATUS_CHANGED';

        SELECT NVL(MAX(EVENT_SEQUENCE), 0) + 1
          INTO V_NEXT_SEQ
          FROM PROCESS_EVENT
         WHERE WORK_ID = V_WORK_ID;

        INSERT INTO PROCESS_EVENT (
            WORK_ID,
            EVENT_TYPE_ID,
            ACCOUNT_ID,
            EVENT_SEQUENCE,
            PUBLIC_YN
        ) VALUES (
            V_WORK_ID,
            V_EVENT_TYPE_ID,
            V_MANAGER_ACC,
            V_NEXT_SEQ,
            'Y'
        )
        RETURNING EVENT_ID INTO V_EVENT_ID;

        -- 상태 변경 이벤트의 변경 전·후 상태와 사유를 상세 테이블에 저장한다.
        INSERT INTO EVENT_STATUS (
            EVENT_ID, BEFORE_STATUS_ID, AFTER_STATUS_ID, STATUS_REASON
        ) VALUES (
            V_EVENT_ID, V_OLD_STATUS_ID, V_STATUS_ID,
            '담당자 배정에 따른 상태 변경'
        );
    END;
BEGIN
    ASSIGN_WORK('[사례2] 시장 주변 쓰레기와 불법주정차',
                'ENVIRONMENT_SANITATION', 'officer105', 'officer104', 'PROCESSING');

    ASSIGN_WORK('[사례2] 시장 주변 쓰레기와 불법주정차',
                'TRAFFIC_SAFETY', 'officer108', 'officer107', 'COMPLETED');

    ASSIGN_WORK('[사례3] 공사장 소음·먼지·보행안전 문제',
                'ENVIRONMENT_SANITATION', 'officer106', 'officer104', 'PROCESSING');

    ASSIGN_WORK('[사례3] 공사장 소음·먼지·보행안전 문제',
                'ARCHITECTURE_URBAN', 'officer123', 'officer122', 'PROCESSING');

    ASSIGN_WORK('[사례3] 공사장 소음·먼지·보행안전 문제',
                'TRAFFIC_SAFETY', 'officer109', 'officer107', 'ASSIGNED');

    ASSIGN_WORK('[사례4] 전통시장 시설·세금·상인 지원 문의',
                'URBAN_FACILITY', 'officer102', 'officer101', 'PROCESSING');

    ASSIGN_WORK('[사례4] 전통시장 시설·세금·상인 지원 문의',
                'ADMINISTRATION_TAX', 'officer117', 'officer116', 'PROCESSING');

    ASSIGN_WORK('[사례4] 전통시장 시설·세금·상인 지원 문의',
                'LOCAL_ECONOMY', 'officer120', 'officer119', 'PROCESSING');

    ASSIGN_WORK('[사례5] 관할 외 기관 민원',
                'GENERAL_REVIEW', 'officer126', 'officer125', 'REJECTED');

    ASSIGN_WORK('[사례6] 횡단보도 신호시간 연장 요청',
                'TRAFFIC_SAFETY', 'officer108', 'officer107', 'COMPLETED');

    ASSIGN_WORK('[사례7] 복지시설 주변 악취 및 안전 문제',
                'ENVIRONMENT_SANITATION', 'officer105', 'officer104', 'PROCESSING');

    ASSIGN_WORK('[사례7] 복지시설 주변 악취 및 안전 문제',
                'WELFARE_SAFETY', 'officer111', 'officer110', 'PROCESSING');

    ASSIGN_WORK('[사례8] 재래시장 건축물·도로·위생 종합 민원',
                'ARCHITECTURE_URBAN', 'officer124', 'officer122', 'COMPLETED');

    ASSIGN_WORK('[사례8] 재래시장 건축물·도로·위생 종합 민원',
                'URBAN_FACILITY', 'officer103', 'officer101', 'COMPLETED');

    ASSIGN_WORK('[사례8] 재래시장 건축물·도로·위생 종합 민원',
                'ENVIRONMENT_SANITATION', 'officer106', 'officer104', 'COMPLETED');
END;
/

-- 사례 7 환경위생 업무의 기존 담당자를 해제하고 새 담당자로 재배정한다.
DECLARE
    V_WORK_ID          NUMBER;
    V_OLD_OFFICER      NUMBER;
    V_NEW_OFFICER      NUMBER;
    V_MANAGER          NUMBER;
    V_UNASSIGN_CODE    NUMBER;
    V_REASSIGN_CODE    NUMBER;
    V_EVENT_TYPE_ID    NUMBER;
    V_NEXT_SEQ         NUMBER;
BEGIN
    SELECT CW.WORK_ID, CW.ACCOUNT_ID
      INTO V_WORK_ID, V_OLD_OFFICER
      FROM COMPLAINT_WORK CW
      JOIN COMPLAINT C ON C.COMPLAINT_ID = CW.COMPLAINT_ID
      JOIN DEPARTMENT D ON D.DEPT_ID = CW.DEPT_ID
     WHERE C.TITLE = '[사례7] 복지시설 주변 악취 및 안전 문제'
       AND D.DEPT_CODE = 'ENVIRONMENT_SANITATION'
       AND CW.ENDED_AT IS NULL;

    SELECT ACCOUNT_ID INTO V_NEW_OFFICER
      FROM ACCOUNT WHERE LOGIN_ID = 'officer106';

    SELECT ACCOUNT_ID INTO V_MANAGER
      FROM ACCOUNT WHERE LOGIN_ID = 'officer104';

    SELECT CC.COMMON_CODE_ID
      INTO V_UNASSIGN_CODE
      FROM COMMON_CODE CC
      JOIN COMMON_CODE_GROUP CG ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
     WHERE CG.GROUP_CODE = 'UNASSIGN_REASON'
       AND CC.CODE_VALUE = 'OFFICER_CHANGED';

    UPDATE WORK_ASSIGNMENT
       SET UNASSIGNED_AT = SYSDATE,
           UNASSIGN_REASON_CODE_ID = V_UNASSIGN_CODE
     WHERE WORK_ID = V_WORK_ID
       AND UNASSIGNED_AT IS NULL;

    SELECT CC.COMMON_CODE_ID
      INTO V_REASSIGN_CODE
      FROM COMMON_CODE CC
      JOIN COMMON_CODE_GROUP CG ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
     WHERE CG.GROUP_CODE = 'ASSIGN_REASON'
       AND CC.CODE_VALUE = 'REASSIGN';

    INSERT INTO WORK_ASSIGNMENT (
        WORK_ID, ACCOUNT_ID, ASSIGNED_BY_ACCOUNT_ID,
        ASSIGN_REASON_CODE_ID, MEMO
    ) VALUES (
        V_WORK_ID, V_NEW_OFFICER, V_MANAGER,
        V_REASSIGN_CODE, '휴가 일정으로 담당자 재배정'
    );

    UPDATE COMPLAINT_WORK
       SET ACCOUNT_ID = V_NEW_OFFICER
     WHERE WORK_ID = V_WORK_ID;

    SELECT EVENT_TYPE_ID INTO V_EVENT_TYPE_ID
      FROM EVENT_TYPE WHERE EVENT_CODE = 'OFFICER_CHANGED';

    SELECT NVL(MAX(EVENT_SEQUENCE), 0) + 1
      INTO V_NEXT_SEQ
      FROM PROCESS_EVENT
     WHERE WORK_ID = V_WORK_ID;

    INSERT INTO PROCESS_EVENT (
        WORK_ID,
        EVENT_TYPE_ID,
        ACCOUNT_ID,
        EVENT_SEQUENCE,
        PUBLIC_YN,
        EVENT_COMMENT
    ) VALUES (
        V_WORK_ID,
        V_EVENT_TYPE_ID,
        V_MANAGER,
        V_NEXT_SEQ,
        'N',
        'env_off1에서 env_off2로 재배정'
    );
END;
/

-- 사례 3의 교통안전 업무를 도시시설 부서로 한 차례 이관한다.
-- 기존 업무 종료, 후속 업무 생성, 이관 이벤트 상세 기록을 하나의 블록에서 처리한다.
DECLARE
    V_OLD_WORK_ID       NUMBER;
    V_NEW_WORK_ID       NUMBER;
    V_COMPLAINT_ID      NUMBER;
    V_MANAGER_ACCOUNT   NUMBER;
    V_TRANSFER_RESULT   NUMBER;
    V_TRANSFER_REASON   NUMBER;
    V_UNASSIGN_REASON   NUMBER;
    V_RECEIVED_STATUS   NUMBER;
    V_EVENT_TYPE_ID     NUMBER;
    V_EVENT_ID          NUMBER;
    V_NEXT_SEQ          NUMBER;
    V_NEW_SEQUENCE      NUMBER;
    V_FROM_DEPT_ID      NUMBER;
    V_TO_DEPT_ID        NUMBER;
BEGIN
    SELECT CW.WORK_ID, CW.COMPLAINT_ID, CW.DEPT_ID
      INTO V_OLD_WORK_ID, V_COMPLAINT_ID, V_FROM_DEPT_ID
      FROM COMPLAINT_WORK CW
      JOIN COMPLAINT C ON C.COMPLAINT_ID = CW.COMPLAINT_ID
      JOIN DEPARTMENT D ON D.DEPT_ID = CW.DEPT_ID
     WHERE C.TITLE = '[사례3] 공사장 소음·먼지·보행안전 문제'
       AND D.DEPT_CODE = 'TRAFFIC_SAFETY'
       AND CW.ENDED_AT IS NULL;

    SELECT DEPT_ID INTO V_TO_DEPT_ID
      FROM DEPARTMENT WHERE DEPT_CODE = 'URBAN_FACILITY';

    SELECT ACCOUNT_ID INTO V_MANAGER_ACCOUNT
      FROM ACCOUNT WHERE LOGIN_ID = 'officer107';

    SELECT CC.COMMON_CODE_ID
      INTO V_TRANSFER_RESULT
      FROM COMMON_CODE CC
      JOIN COMMON_CODE_GROUP CG ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
     WHERE CG.GROUP_CODE = 'WORK_RESULT'
       AND CC.CODE_VALUE = 'TRANSFERRED';

    SELECT CC.COMMON_CODE_ID
      INTO V_TRANSFER_REASON
      FROM COMMON_CODE CC
      JOIN COMMON_CODE_GROUP CG ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
     WHERE CG.GROUP_CODE = 'TRANSFER_REASON'
       AND CC.CODE_VALUE = 'MIS_ASSIGNED';

    SELECT CC.COMMON_CODE_ID
      INTO V_UNASSIGN_REASON
      FROM COMMON_CODE CC
      JOIN COMMON_CODE_GROUP CG ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
     WHERE CG.GROUP_CODE = 'UNASSIGN_REASON'
       AND CC.CODE_VALUE = 'DEPARTMENT_TRANSFERRED';

    UPDATE WORK_ASSIGNMENT
       SET UNASSIGNED_AT = SYSDATE,
           UNASSIGN_REASON_CODE_ID = V_UNASSIGN_REASON
     WHERE WORK_ID = V_OLD_WORK_ID
       AND UNASSIGNED_AT IS NULL;

    UPDATE COMPLAINT_WORK
       SET ACCOUNT_ID = NULL,
           ENDED_AT = SYSDATE,
           WORK_RESULT_CODE_ID = V_TRANSFER_RESULT,
           ENABLED = 'N'
     WHERE WORK_ID = V_OLD_WORK_ID;

    SELECT STATUS_ID INTO V_RECEIVED_STATUS
      FROM STATUS WHERE STATUS_CODE = 'RECEIVED';

    SELECT MAX(WORK_SEQUENCE) + 1
      INTO V_NEW_SEQUENCE
      FROM COMPLAINT_WORK
     WHERE COMPLAINT_ID = V_COMPLAINT_ID;

    INSERT INTO COMPLAINT_WORK (
        COMPLAINT_ID, PARENT_WORK_ID, DEPT_ID, ACCOUNT_ID,
        STATUS_ID, WORK_SEQUENCE, CREATED_BY_ACCOUNT_ID
    ) VALUES (
        V_COMPLAINT_ID, V_OLD_WORK_ID, V_TO_DEPT_ID, NULL,
        V_RECEIVED_STATUS, V_NEW_SEQUENCE, V_MANAGER_ACCOUNT
    )
    RETURNING WORK_ID INTO V_NEW_WORK_ID;

    SELECT EVENT_TYPE_ID INTO V_EVENT_TYPE_ID
      FROM EVENT_TYPE WHERE EVENT_CODE = 'DEPARTMENT_TRANSFERRED';

    SELECT NVL(MAX(EVENT_SEQUENCE), 0) + 1
      INTO V_NEXT_SEQ
      FROM PROCESS_EVENT
     WHERE WORK_ID = V_OLD_WORK_ID;

    INSERT INTO PROCESS_EVENT (
        WORK_ID,
        EVENT_TYPE_ID,
        ACCOUNT_ID,
        EVENT_SEQUENCE,
        PUBLIC_YN,
        EVENT_COMMENT
    ) VALUES (
        V_OLD_WORK_ID,
        V_EVENT_TYPE_ID,
        V_MANAGER_ACCOUNT,
        V_NEXT_SEQ,
        'Y',
        '교통안전에서 도시시설로 이관'
    )
    RETURNING EVENT_ID INTO V_EVENT_ID;

    INSERT INTO EVENT_TRANSFER (
        EVENT_ID, FROM_DEPT_ID, TO_DEPT_ID,
        TRANSFER_REASON_CODE_ID, TRANSFER_REASON_DETAIL, NEW_WORK_ID
    ) VALUES (
        V_EVENT_ID, V_FROM_DEPT_ID, V_TO_DEPT_ID,
        V_TRANSFER_REASON, '도로 시설물 소관으로 판단되어 이관', V_NEW_WORK_ID
    );

    SELECT EVENT_TYPE_ID INTO V_EVENT_TYPE_ID
      FROM EVENT_TYPE WHERE EVENT_CODE = 'WORK_CREATED';

    INSERT INTO PROCESS_EVENT (
        WORK_ID,
        EVENT_TYPE_ID,
        ACCOUNT_ID,
        EVENT_SEQUENCE,
        PUBLIC_YN,
        EVENT_COMMENT
    ) VALUES (
        V_NEW_WORK_ID,
        V_EVENT_TYPE_ID,
        V_MANAGER_ACCOUNT,
        1,
        'Y',
        '교통안전 업무에서 이관되어 생성'
    );
END;
/

-- 사례 4의 여러 부서 이관을 반복 처리하기 위한 TRANSFER_WORK 프로시저이다.
DECLARE
    PROCEDURE TRANSFER_WORK (
        P_TITLE          VARCHAR2,
        P_FROM_DEPT_CODE VARCHAR2,
        P_TO_DEPT_CODE   VARCHAR2,
        P_MANAGER_LOGIN  VARCHAR2,
        P_REASON_VALUE   VARCHAR2,
        P_REASON_DETAIL  VARCHAR2
    ) IS
        V_OLD_WORK_ID       NUMBER;
        V_NEW_WORK_ID       NUMBER;
        V_COMPLAINT_ID      NUMBER;
        V_MANAGER_ACCOUNT   NUMBER;
        V_TRANSFER_RESULT   NUMBER;
        V_TRANSFER_REASON   NUMBER;
        V_UNASSIGN_REASON   NUMBER;
        V_RECEIVED_STATUS   NUMBER;
        V_EVENT_TYPE_ID     NUMBER;
        V_EVENT_ID          NUMBER;
        V_NEXT_SEQ          NUMBER;
        V_NEW_SEQUENCE      NUMBER;
        V_FROM_DEPT_ID      NUMBER;
        V_TO_DEPT_ID        NUMBER;
    BEGIN
        SELECT CW.WORK_ID, CW.COMPLAINT_ID, CW.DEPT_ID
          INTO V_OLD_WORK_ID, V_COMPLAINT_ID, V_FROM_DEPT_ID
          FROM COMPLAINT_WORK CW
          JOIN COMPLAINT C ON C.COMPLAINT_ID = CW.COMPLAINT_ID
          JOIN DEPARTMENT D ON D.DEPT_ID = CW.DEPT_ID
         WHERE C.TITLE = P_TITLE
           AND D.DEPT_CODE = P_FROM_DEPT_CODE
           AND CW.ENDED_AT IS NULL;

        SELECT DEPT_ID INTO V_TO_DEPT_ID
          FROM DEPARTMENT WHERE DEPT_CODE = P_TO_DEPT_CODE;

        SELECT ACCOUNT_ID INTO V_MANAGER_ACCOUNT
          FROM ACCOUNT WHERE LOGIN_ID = P_MANAGER_LOGIN;

        SELECT CC.COMMON_CODE_ID
          INTO V_TRANSFER_RESULT
          FROM COMMON_CODE CC
          JOIN COMMON_CODE_GROUP CG ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
         WHERE CG.GROUP_CODE = 'WORK_RESULT'
           AND CC.CODE_VALUE = 'TRANSFERRED';

        SELECT CC.COMMON_CODE_ID
          INTO V_TRANSFER_REASON
          FROM COMMON_CODE CC
          JOIN COMMON_CODE_GROUP CG ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
         WHERE CG.GROUP_CODE = 'TRANSFER_REASON'
           AND CC.CODE_VALUE = P_REASON_VALUE;

        SELECT CC.COMMON_CODE_ID
          INTO V_UNASSIGN_REASON
          FROM COMMON_CODE CC
          JOIN COMMON_CODE_GROUP CG ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
         WHERE CG.GROUP_CODE = 'UNASSIGN_REASON'
           AND CC.CODE_VALUE = 'DEPARTMENT_TRANSFERRED';

        UPDATE WORK_ASSIGNMENT
           SET UNASSIGNED_AT = SYSDATE,
               UNASSIGN_REASON_CODE_ID = V_UNASSIGN_REASON
         WHERE WORK_ID = V_OLD_WORK_ID
           AND UNASSIGNED_AT IS NULL;

        UPDATE COMPLAINT_WORK
           SET ACCOUNT_ID = NULL,
               ENDED_AT = SYSDATE,
               WORK_RESULT_CODE_ID = V_TRANSFER_RESULT,
               ENABLED = 'N'
         WHERE WORK_ID = V_OLD_WORK_ID;

        SELECT STATUS_ID INTO V_RECEIVED_STATUS
          FROM STATUS WHERE STATUS_CODE = 'RECEIVED';

        SELECT MAX(WORK_SEQUENCE) + 1
          INTO V_NEW_SEQUENCE
          FROM COMPLAINT_WORK
         WHERE COMPLAINT_ID = V_COMPLAINT_ID;

        INSERT INTO COMPLAINT_WORK (
            COMPLAINT_ID, PARENT_WORK_ID, DEPT_ID, ACCOUNT_ID,
            STATUS_ID, WORK_SEQUENCE, CREATED_BY_ACCOUNT_ID
        ) VALUES (
            V_COMPLAINT_ID, V_OLD_WORK_ID, V_TO_DEPT_ID, NULL,
            V_RECEIVED_STATUS, V_NEW_SEQUENCE, V_MANAGER_ACCOUNT
        )
        RETURNING WORK_ID INTO V_NEW_WORK_ID;

        SELECT EVENT_TYPE_ID INTO V_EVENT_TYPE_ID
          FROM EVENT_TYPE WHERE EVENT_CODE = 'DEPARTMENT_TRANSFERRED';

        SELECT NVL(MAX(EVENT_SEQUENCE), 0) + 1
          INTO V_NEXT_SEQ
          FROM PROCESS_EVENT
         WHERE WORK_ID = V_OLD_WORK_ID;

        INSERT INTO PROCESS_EVENT (
            WORK_ID,
            EVENT_TYPE_ID,
            ACCOUNT_ID,
            EVENT_SEQUENCE,
            PUBLIC_YN,
            EVENT_COMMENT
        ) VALUES (
            V_OLD_WORK_ID,
            V_EVENT_TYPE_ID,
            V_MANAGER_ACCOUNT,
            V_NEXT_SEQ,
            'Y',
            P_REASON_DETAIL
        )
        RETURNING EVENT_ID INTO V_EVENT_ID;

        INSERT INTO EVENT_TRANSFER (
            EVENT_ID, FROM_DEPT_ID, TO_DEPT_ID,
            TRANSFER_REASON_CODE_ID, TRANSFER_REASON_DETAIL, NEW_WORK_ID
        ) VALUES (
            V_EVENT_ID, V_FROM_DEPT_ID, V_TO_DEPT_ID,
            V_TRANSFER_REASON, P_REASON_DETAIL, V_NEW_WORK_ID
        );

        SELECT EVENT_TYPE_ID INTO V_EVENT_TYPE_ID
          FROM EVENT_TYPE WHERE EVENT_CODE = 'WORK_CREATED';

        INSERT INTO PROCESS_EVENT (
            WORK_ID,
            EVENT_TYPE_ID,
            ACCOUNT_ID,
            EVENT_SEQUENCE,
            PUBLIC_YN,
            EVENT_COMMENT
        ) VALUES (
            V_NEW_WORK_ID,
            V_EVENT_TYPE_ID,
            V_MANAGER_ACCOUNT,
            1,
            'Y',
            P_FROM_DEPT_CODE || '에서 이관되어 생성'
        );
    END;
BEGIN
    TRANSFER_WORK(
        '[사례4] 전통시장 시설·세금·상인 지원 문의',
        'URBAN_FACILITY',
        'ARCHITECTURE_URBAN',
        'officer101',
        'JURISDICTION_CHANGE',
        '시장 시설물이 건축물 안전 검토 대상이어서 건축도시로 이관'
    );

    TRANSFER_WORK(
        '[사례4] 전통시장 시설·세금·상인 지원 문의',
        'ADMINISTRATION_TAX',
        'ADMINISTRATION_COMPLAINT',
        'officer116',
        'JURISDICTION_CHANGE',
        '세금 부과 문제가 아니라 일반 행정 안내에 해당하여 행정민원으로 이관'
    );
END;
/

-- 완료된 업무에 답변을 등록하고 종료 결과 및 답변 완료 이벤트를 기록한다.
DECLARE
    PROCEDURE COMPLETE_WORK (
        P_TITLE          VARCHAR2,
        P_DEPT_CODE      VARCHAR2,
        P_OFFICER_LOGIN  VARCHAR2,
        P_REPLY_TITLE    VARCHAR2,
        P_REPLY_CONTENT  VARCHAR2
    ) IS
        V_WORK_ID       NUMBER;
        V_OFFICER_ID    NUMBER;
        V_RESULT_ID     NUMBER;
        V_EVENT_TYPE_ID NUMBER;
        V_NEXT_SEQ      NUMBER;
    BEGIN
        SELECT CW.WORK_ID
          INTO V_WORK_ID
          FROM COMPLAINT_WORK CW
          JOIN COMPLAINT C ON C.COMPLAINT_ID = CW.COMPLAINT_ID
          JOIN DEPARTMENT D ON D.DEPT_ID = CW.DEPT_ID
         WHERE C.TITLE = P_TITLE
           AND D.DEPT_CODE = P_DEPT_CODE
           AND CW.ENDED_AT IS NULL;

        SELECT ACCOUNT_ID INTO V_OFFICER_ID
          FROM ACCOUNT WHERE LOGIN_ID = P_OFFICER_LOGIN;

        INSERT INTO REPLY (
            WORK_ID, ACCOUNT_ID, TITLE, CONTENT
        ) VALUES (
            V_WORK_ID, V_OFFICER_ID, P_REPLY_TITLE, P_REPLY_CONTENT
        );

        SELECT CC.COMMON_CODE_ID
          INTO V_RESULT_ID
          FROM COMMON_CODE CC
          JOIN COMMON_CODE_GROUP CG ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
         WHERE CG.GROUP_CODE = 'WORK_RESULT'
           AND CC.CODE_VALUE = 'COMPLETED';

        UPDATE COMPLAINT_WORK
           SET ENDED_AT = SYSDATE,
               WORK_RESULT_CODE_ID = V_RESULT_ID,
               ENABLED = 'N'
         WHERE WORK_ID = V_WORK_ID;

        SELECT EVENT_TYPE_ID INTO V_EVENT_TYPE_ID
          FROM EVENT_TYPE WHERE EVENT_CODE = 'REPLY_COMPLETED';

        SELECT NVL(MAX(EVENT_SEQUENCE), 0) + 1
          INTO V_NEXT_SEQ
          FROM PROCESS_EVENT
         WHERE WORK_ID = V_WORK_ID;

        INSERT INTO PROCESS_EVENT (
            WORK_ID,
            EVENT_TYPE_ID,
            ACCOUNT_ID,
            EVENT_SEQUENCE,
            PUBLIC_YN
        ) VALUES (
            V_WORK_ID,
            V_EVENT_TYPE_ID,
            V_OFFICER_ID,
            V_NEXT_SEQ,
            'Y'
        );
    END;
BEGIN
    COMPLETE_WORK(
        '[사례2] 시장 주변 쓰레기와 불법주정차',
        'TRAFFIC_SAFETY',
        'officer108',
        '불법주정차 단속 결과',
        '현장 점검 후 불법주정차 단속을 실시했습니다.'
    );

    COMPLETE_WORK(
        '[사례6] 횡단보도 신호시간 연장 요청',
        'TRAFFIC_SAFETY',
        'officer108',
        '보행신호 시간 검토 결과',
        '현장 조사 후 보행신호 시간을 조정하기로 했습니다.'
    );

    COMPLETE_WORK(
        '[사례8] 재래시장 건축물·도로·위생 종합 민원',
        'ARCHITECTURE_URBAN',
        'officer124',
        '건축물 안전점검 결과',
        '현장 안전점검을 완료하고 보수 권고를 전달했습니다.'
    );

    COMPLETE_WORK(
        '[사례8] 재래시장 건축물·도로·위생 종합 민원',
        'URBAN_FACILITY',
        'officer103',
        '도로 보수 결과',
        '시장 주변 파손 도로의 임시 보수를 완료했습니다.'
    );

    COMPLETE_WORK(
        '[사례8] 재래시장 건축물·도로·위생 종합 민원',
        'ENVIRONMENT_SANITATION',
        'officer106',
        '폐기물 정비 결과',
        '적치 폐기물을 수거하고 정기 점검 대상으로 등록했습니다.'
    );
END;
/

-- 관할 외 민원을 반려 처리하고 WORK_REJECTED 이벤트를 기록한다.
DECLARE
    V_WORK_ID       NUMBER;
    V_RESULT_ID     NUMBER;
    V_OFFICER_ID    NUMBER;
    V_EVENT_TYPE_ID NUMBER;
    V_NEXT_SEQ      NUMBER;
BEGIN
    SELECT CW.WORK_ID, CW.ACCOUNT_ID
      INTO V_WORK_ID, V_OFFICER_ID
      FROM COMPLAINT_WORK CW
      JOIN COMPLAINT C ON C.COMPLAINT_ID = CW.COMPLAINT_ID
     WHERE C.TITLE = '[사례5] 관할 외 기관 민원'
       AND CW.ENDED_AT IS NULL;

    SELECT CC.COMMON_CODE_ID
      INTO V_RESULT_ID
      FROM COMMON_CODE CC
      JOIN COMMON_CODE_GROUP CG ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
     WHERE CG.GROUP_CODE = 'WORK_RESULT'
       AND CC.CODE_VALUE = 'REJECTED';

    UPDATE COMPLAINT_WORK
       SET ENDED_AT = SYSDATE,
           WORK_RESULT_CODE_ID = V_RESULT_ID,
           ENABLED = 'N'
     WHERE WORK_ID = V_WORK_ID;

    SELECT EVENT_TYPE_ID INTO V_EVENT_TYPE_ID
      FROM EVENT_TYPE WHERE EVENT_CODE = 'WORK_REJECTED';

    SELECT NVL(MAX(EVENT_SEQUENCE), 0) + 1
      INTO V_NEXT_SEQ
      FROM PROCESS_EVENT
     WHERE WORK_ID = V_WORK_ID;

    INSERT INTO PROCESS_EVENT (
        WORK_ID,
        EVENT_TYPE_ID,
        ACCOUNT_ID,
        EVENT_SEQUENCE,
        PUBLIC_YN,
        EVENT_COMMENT
    ) VALUES (
        V_WORK_ID,
        V_EVENT_TYPE_ID,
        V_OFFICER_ID,
        V_NEXT_SEQ,
        'Y',
        '해당 기관의 소관 업무가 아니어서 반려'
    );
END;
/

