-- 사례 1~8과 관련 기준 데이터를 데이터베이스에 확정한다.
COMMIT;

-- ============================================================================
-- 8. 사례 1~8 생성 결과 확인
-- ============================================================================
-- 부서별 공무원 수를 확인한다.
SELECT D.DEPT_CODE,
       D.DEPT_NAME,
       COUNT(O.ACCOUNT_ID) AS OFFICER_COUNT
  FROM DEPARTMENT D
  LEFT JOIN OFFICER O
    ON O.DEPT_ID = D.DEPT_ID
 GROUP BY D.DEPT_ID, D.DEPT_CODE, D.DEPT_NAME
 ORDER BY D.DEPT_ID;

-- 민원별 최초 부서 업무 수가 최대 3개인지 확인한다.
SELECT C.COMPLAINT_ID,
       C.TITLE,
       COUNT(CW.WORK_ID) AS INITIAL_WORK_COUNT
  FROM COMPLAINT C
  LEFT JOIN COMPLAINT_WORK CW
    ON CW.COMPLAINT_ID = C.COMPLAINT_ID
   AND CW.PARENT_WORK_ID IS NULL
 GROUP BY C.COMPLAINT_ID, C.TITLE
 ORDER BY C.COMPLAINT_ID;

-- 민원별 부서 이관 횟수를 확인한다.
SELECT C.COMPLAINT_ID,
       C.TITLE,
       COUNT(ETF.EVENT_ID) AS TRANSFER_COUNT
  FROM COMPLAINT C
  LEFT JOIN COMPLAINT_WORK CW
    ON CW.COMPLAINT_ID = C.COMPLAINT_ID
  LEFT JOIN PROCESS_EVENT PE
    ON PE.WORK_ID = CW.WORK_ID
  LEFT JOIN EVENT_TRANSFER ETF
    ON ETF.EVENT_ID = PE.EVENT_ID
 GROUP BY C.COMPLAINT_ID, C.TITLE
 ORDER BY C.COMPLAINT_ID;

-- 모든 민원의 부서별 담당자와 현재 상태, 처리 기간을 확인한다.
SELECT C.TITLE,
       CW.WORK_ID,
       CW.PARENT_WORK_ID,
       D.DEPT_NAME,
       O.NAME AS CURRENT_OFFICER,
       S.STATUS_NAME,
       CW.STARTED_AT,
       CW.ENDED_AT
  FROM COMPLAINT C
  JOIN COMPLAINT_WORK CW
    ON CW.COMPLAINT_ID = C.COMPLAINT_ID
  JOIN DEPARTMENT D
    ON D.DEPT_ID = CW.DEPT_ID
  LEFT JOIN OFFICER O
    ON O.ACCOUNT_ID = CW.ACCOUNT_ID
  JOIN STATUS S
    ON S.STATUS_ID = CW.STATUS_ID
 ORDER BY C.COMPLAINT_ID, CW.WORK_SEQUENCE;

-- 생성된 일반 회원 및 공무원 계정의 유형과 활성화 상태를 확인한다.
SELECT ACCOUNT_ID,
       LOGIN_ID,
       ACCOUNT_TYPE,
       ENABLED
  FROM ACCOUNT
 WHERE LOGIN_ID LIKE 'user%'
    OR LOGIN_ID LIKE 'officer%'
 ORDER BY ACCOUNT_ID;

