DECLARE
    V_EVENT_ID NUMBER;
BEGIN
    INSERT INTO PROCESS_EVENT (
        WORK_ID,
        EVENT_TYPE_ID,
        ACCOUNT_ID,
        EVENT_SEQUENCE,
        EVENT_TIME,
        PUBLIC_YN,
        EVENT_COMMENT
    )
    SELECT
        CW.WORK_ID,
        ET.EVENT_TYPE_ID,
        123,
        3,
        TO_DATE('2026-07-01 13:00:00', 'YYYY-MM-DD HH24:MI:SS'),
        'Y',
        '접수 상태에서 COMPLETED 상태로 변경'
    FROM COMPLAINT_WORK CW
      JOIN COMPLAINT C ON C.COMPLAINT_ID = CW.COMPLAINT_ID
      JOIN DEPARTMENT D ON D.DEPT_ID = CW.DEPT_ID
      JOIN EVENT_TYPE ET ON ET.EVENT_CODE = 'STATUS_CHANGED'
     WHERE C.TITLE = '[사례21] 공동주택 외벽 균열 신고'
       AND D.DEPT_CODE = 'ARCHITECTURE_URBAN';

    SELECT MAX(EVENT_ID)
      INTO V_EVENT_ID
      FROM PROCESS_EVENT;

    INSERT INTO EVENT_STATUS (
        EVENT_ID, BEFORE_STATUS_ID, AFTER_STATUS_ID, STATUS_REASON
    )
    SELECT V_EVENT_ID,
           B.STATUS_ID,
           A.STATUS_ID,
           '추가 더미데이터 상태 변경'
      FROM STATUS B
      JOIN STATUS A ON 1 = 1
     WHERE B.STATUS_CODE = 'RECEIVED'
       AND A.STATUS_CODE = 'COMPLETED';
END;
/

