  JOIN DEPARTMENT D ON D.DEPT_ID = CW.DEPT_ID
  JOIN EVENT_TYPE ET ON ET.EVENT_CODE = 'OFFICER_ASSIGNED'
 WHERE C.TITLE = '[사례26] 복지관 시설 보수 요청'
   AND D.DEPT_CODE = 'WELFARE_SAFETY';

DECLARE
    V_EVENT_ID NUMBER;
BEGIN
    INSERT INTO PROCESS_EVENT (
        WORK_ID,
        EVENT_TYPE_ID,
        ACCOUNT_ID,
        EVENT_SEQUENCE,
        EVENT_TIME,
        PUBLIC_YN,
        EVENT_COMMENT
    )
    SELECT
        CW.WORK_ID,
        ET.EVENT_TYPE_ID,
        111,
        3,
        TO_DATE('2026-07-06 13:00:00', 'YYYY-MM-DD HH24:MI:SS'),
        'Y',
        '접수 상태에서 PROCESSING 상태로 변경'
    FROM COMPLAINT_WORK CW
      JOIN COMPLAINT C ON C.COMPLAINT_ID = CW.COMPLAINT_ID
      JOIN DEPARTMENT D ON D.DEPT_ID = CW.DEPT_ID
      JOIN EVENT_TYPE ET ON ET.EVENT_CODE = 'STATUS_CHANGED'
     WHERE C.TITLE = '[사례26] 복지관 시설 보수 요청'
       AND D.DEPT_CODE = 'WELFARE_SAFETY';

    SELECT MAX(EVENT_ID)
      INTO V_EVENT_ID
      FROM PROCESS_EVENT;

    INSERT INTO EVENT_STATUS (
        EVENT_ID, BEFORE_STATUS_ID, AFTER_STATUS_ID, STATUS_REASON
    )
    SELECT V_EVENT_ID,
           B.STATUS_ID,
           A.STATUS_ID,
           '추가 더미데이터 상태 변경'
      FROM STATUS B
      JOIN STATUS A ON 1 = 1
     WHERE B.STATUS_CODE = 'RECEIVED'
       AND A.STATUS_CODE = 'PROCESSING';
END;
/

