-- 사례 9~28의 추가 데이터를 확정한다.
COMMIT;

-- ============================================================================
-- 10. 사례 9~28 생성 결과 확인
-- ============================================================================
-- 현재까지 등록된 전체 민원 수를 확인한다.
SELECT COUNT(*) AS COMPLAINT_COUNT
  FROM COMPLAINT;

-- 민원별 최초 분리 업무 개수를 확인한다.
SELECT C.COMPLAINT_ID,
       C.TITLE,
       COUNT(CW.WORK_ID) AS INITIAL_DEPARTMENT_COUNT
  FROM COMPLAINT C
  JOIN COMPLAINT_WORK CW
    ON CW.COMPLAINT_ID = C.COMPLAINT_ID
   AND CW.PARENT_WORK_ID IS NULL
 GROUP BY C.COMPLAINT_ID, C.TITLE
 ORDER BY C.COMPLAINT_ID;

-- 부서와 처리 상태별 업무 건수를 집계한다.
SELECT D.DEPT_NAME,
       S.STATUS_NAME,
       COUNT(*) AS WORK_COUNT
  FROM COMPLAINT_WORK CW
  JOIN DEPARTMENT D ON D.DEPT_ID = CW.DEPT_ID
  JOIN STATUS S ON S.STATUS_ID = CW.STATUS_ID
 GROUP BY D.DEPT_ID, D.DEPT_NAME, S.STATUS_ID, S.STATUS_NAME
 ORDER BY D.DEPT_ID, S.STATUS_ID;

-- 모든 민원의 부서, 담당자, 상태, 생성·종료 시각을 조회한다.
SELECT C.COMPLAINT_ID,
       C.TITLE,
       D.DEPT_NAME,
       O.NAME AS OFFICER_NAME,
       S.STATUS_NAME,
       CW.CREATED_AT,
       CW.ENDED_AT
  FROM COMPLAINT C
  JOIN COMPLAINT_WORK CW ON CW.COMPLAINT_ID = C.COMPLAINT_ID
  JOIN DEPARTMENT D ON D.DEPT_ID = CW.DEPT_ID
  LEFT JOIN OFFICER O ON O.ACCOUNT_ID = CW.ACCOUNT_ID
 JOIN STATUS S ON S.STATUS_ID = CW.STATUS_ID
 ORDER BY C.COMPLAINT_ID, CW.WORK_SEQUENCE;

-- ============================================================================
-- 11. 업무 규칙에 맞춘 데이터 보정
-- ============================================================================
-- 일반소관확인 부서는 직접 반려할 수 없다는 규칙에 맞게 처리중 상태로 되돌린다.
DECLARE
    V_PROCESSING_STATUS NUMBER;
BEGIN
    SELECT STATUS_ID
      INTO V_PROCESSING_STATUS
      FROM STATUS
     WHERE STATUS_CODE = 'PROCESSING';

    -- 잘못 반려된 일반소관확인 업무를 처리중·활성 상태로 보정한다.
    UPDATE COMPLAINT_WORK CW
       SET CW.STATUS_ID = V_PROCESSING_STATUS,
           CW.WORK_RESULT_CODE_ID = NULL,
           CW.ENDED_AT = NULL,
           CW.ENABLED = 'Y',
           CW.UPDATED_AT = SYSDATE
     WHERE CW.WORK_ID IN (
           SELECT CW2.WORK_ID
             FROM COMPLAINT_WORK CW2
             JOIN DEPARTMENT D
               ON D.DEPT_ID = CW2.DEPT_ID
            WHERE D.DEPT_CODE = 'GENERAL_REVIEW'
              AND CW2.STATUS_ID = (
                    SELECT STATUS_ID
                      FROM STATUS
                     WHERE STATUS_CODE = 'REJECTED'
              )
     );

    -- 보정 대상 업무에 기록된 반려 이벤트를 삭제한다.
    DELETE FROM PROCESS_EVENT PE
     WHERE PE.EVENT_TYPE_ID = (
           SELECT EVENT_TYPE_ID
             FROM EVENT_TYPE
            WHERE EVENT_CODE = 'WORK_REJECTED'
     )
       AND PE.WORK_ID IN (
           SELECT CW.WORK_ID
             FROM COMPLAINT_WORK CW
             JOIN DEPARTMENT D
               ON D.DEPT_ID = CW.DEPT_ID
            WHERE D.DEPT_CODE = 'GENERAL_REVIEW'
     );

    -- 상태 변경 상세 이력도 처리중 상태와 보정 사유에 맞게 수정한다.
    UPDATE EVENT_STATUS ES
       SET ES.AFTER_STATUS_ID = V_PROCESSING_STATUS,
           ES.STATUS_REASON = '일반소관확인 부서는 반려할 수 없어 처리중으로 보정'
     WHERE ES.EVENT_ID IN (
           SELECT PE.EVENT_ID
             FROM PROCESS_EVENT PE
             JOIN COMPLAINT_WORK CW
               ON CW.WORK_ID = PE.WORK_ID
             JOIN DEPARTMENT D
               ON D.DEPT_ID = CW.DEPT_ID
            WHERE D.DEPT_CODE = 'GENERAL_REVIEW'
              AND PE.EVENT_TYPE_ID = (
                    SELECT EVENT_TYPE_ID
                      FROM EVENT_TYPE
                     WHERE EVENT_CODE = 'STATUS_CHANGED'
              )
     );
END;
/

-- 모든 업무가 비활성화된 민원은 가장 마지막 업무 하나를 다시 활성화한다.
-- ROW_NUMBER와 SUM 분석 함수를 사용하여 민원별 마지막 업무와 활성 업무 수를 계산한다.
MERGE INTO COMPLAINT_WORK TARGET
USING (
    SELECT WORK_ID
      FROM (
            SELECT CW.WORK_ID,
                   ROW_NUMBER() OVER (
                       PARTITION BY CW.COMPLAINT_ID
                       ORDER BY CW.WORK_SEQUENCE DESC, CW.WORK_ID DESC
                   ) AS RN,
                   SUM(
                       CASE WHEN CW.ENABLED = 'Y' THEN 1 ELSE 0 END
                   ) OVER (
                       PARTITION BY CW.COMPLAINT_ID
                   ) AS ACTIVE_COUNT
              FROM COMPLAINT_WORK CW
      )
     WHERE RN = 1
       AND ACTIVE_COUNT = 0
) SOURCE
ON (TARGET.WORK_ID = SOURCE.WORK_ID)
WHEN MATCHED THEN
    UPDATE SET TARGET.ENABLED = 'Y',
               TARGET.UPDATED_AT = SYSDATE;

-- ============================================================================
-- 12. 핵심 업무 규칙 검증용 데이터: 규칙사례 29~34
-- ============================================================================
-- 반려 후 활성 업무 유지, 최대 2회 이관, 일반소관확인 반려 금지를 검증한다.
DECLARE
    V_COMPLAINT_ID       NUMBER;
    V_URBAN_WORK_ID      NUMBER;
    V_TRAFFIC_WORK_ID    NUMBER;
    V_PROCESSING_STATUS  NUMBER;
    V_REJECTED_STATUS    NUMBER;
    V_REJECT_RESULT      NUMBER;
    V_WORK_CREATED_EVENT NUMBER;
    V_REJECT_EVENT       NUMBER;
    V_URBAN_DEPT         NUMBER;
    V_TRAFFIC_DEPT       NUMBER;
BEGIN
    SELECT STATUS_ID INTO V_PROCESSING_STATUS
      FROM STATUS WHERE STATUS_CODE = 'PROCESSING';

    SELECT STATUS_ID INTO V_REJECTED_STATUS
      FROM STATUS WHERE STATUS_CODE = 'REJECTED';

    SELECT CC.COMMON_CODE_ID
      INTO V_REJECT_RESULT
      FROM COMMON_CODE CC
      JOIN COMMON_CODE_GROUP CG
        ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
     WHERE CG.GROUP_CODE = 'WORK_RESULT'
       AND CC.CODE_VALUE = 'REJECTED';

    SELECT EVENT_TYPE_ID INTO V_WORK_CREATED_EVENT
      FROM EVENT_TYPE WHERE EVENT_CODE = 'WORK_CREATED';

    SELECT EVENT_TYPE_ID INTO V_REJECT_EVENT
