INSERT INTO COMPLAINT_WORK (
    COMPLAINT_ID, PARENT_WORK_ID, DEPT_ID, ACCOUNT_ID,
    STATUS_ID, WORK_SEQUENCE, ENABLED,
    CREATED_AT, UPDATED_AT
)
SELECT C.COMPLAINT_ID,
       NULL,
       D.DEPT_ID,
       126,
       S.STATUS_ID,
       1,
       'Y',
       TO_DATE('2026-07-14 10:00:00', 'YYYY-MM-DD HH24:MI:SS'),
       TO_DATE('2026-07-14 10:00:00', 'YYYY-MM-DD HH24:MI:SS')
  FROM COMPLAINT C
  JOIN DEPARTMENT D
    ON D.DEPT_CODE = 'GENERAL_REVIEW'
  JOIN STATUS S
    ON S.STATUS_CODE = 'PROCESSING'
 WHERE C.TITLE = '[규칙사례33] 일반소관확인 총괄 검토';

DECLARE
    V_COMPLAINT_ID       NUMBER;
    V_ACTIVE_WORK        NUMBER;
    V_WORK1              NUMBER;
    V_WORK2              NUMBER;
    V_WORK3              NUMBER;
    V_WELFARE_DEPT       NUMBER;
    V_ARCH_DEPT          NUMBER;
    V_URBAN_DEPT         NUMBER;
    V_TRAFFIC_DEPT       NUMBER;
    V_PROCESSING_STATUS  NUMBER;
    V_RECEIVED_STATUS    NUMBER;
    V_REJECTED_STATUS    NUMBER;
    V_TRANSFER_RESULT    NUMBER;
    V_REJECT_RESULT      NUMBER;
    V_TRANSFER_REASON    NUMBER;
    V_TRANSFER_EVENT     NUMBER;
    V_REJECT_EVENT       NUMBER;
    V_EVENT_ID           NUMBER;
BEGIN
    SELECT DEPT_ID INTO V_WELFARE_DEPT
      FROM DEPARTMENT WHERE DEPT_CODE = 'WELFARE_SAFETY';

    SELECT DEPT_ID INTO V_ARCH_DEPT
      FROM DEPARTMENT WHERE DEPT_CODE = 'ARCHITECTURE_URBAN';

    SELECT DEPT_ID INTO V_URBAN_DEPT
      FROM DEPARTMENT WHERE DEPT_CODE = 'URBAN_FACILITY';

    SELECT DEPT_ID INTO V_TRAFFIC_DEPT
      FROM DEPARTMENT WHERE DEPT_CODE = 'TRAFFIC_SAFETY';

    SELECT STATUS_ID INTO V_PROCESSING_STATUS
      FROM STATUS WHERE STATUS_CODE = 'PROCESSING';

    SELECT STATUS_ID INTO V_RECEIVED_STATUS
      FROM STATUS WHERE STATUS_CODE = 'RECEIVED';

    SELECT STATUS_ID INTO V_REJECTED_STATUS
      FROM STATUS WHERE STATUS_CODE = 'REJECTED';

    SELECT CC.COMMON_CODE_ID INTO V_TRANSFER_RESULT
      FROM COMMON_CODE CC
      JOIN COMMON_CODE_GROUP CG
        ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
     WHERE CG.GROUP_CODE = 'WORK_RESULT'
       AND CC.CODE_VALUE = 'TRANSFERRED';

    SELECT CC.COMMON_CODE_ID INTO V_REJECT_RESULT
      FROM COMMON_CODE CC
      JOIN COMMON_CODE_GROUP CG
        ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
     WHERE CG.GROUP_CODE = 'WORK_RESULT'
       AND CC.CODE_VALUE = 'REJECTED';

    SELECT CC.COMMON_CODE_ID INTO V_TRANSFER_REASON
      FROM COMMON_CODE CC
      JOIN COMMON_CODE_GROUP CG
        ON CG.CODE_GROUP_ID = CC.CODE_GROUP_ID
     WHERE CG.GROUP_CODE = 'TRANSFER_REASON'
       AND CC.CODE_VALUE = 'JURISDICTION_CHANGE';

    SELECT EVENT_TYPE_ID INTO V_TRANSFER_EVENT
      FROM EVENT_TYPE WHERE EVENT_CODE = 'DEPARTMENT_TRANSFERRED';

    SELECT EVENT_TYPE_ID INTO V_REJECT_EVENT
      FROM EVENT_TYPE WHERE EVENT_CODE = 'WORK_REJECTED';

    -- 규칙사례 34: 이관 초과 업무를 반려하되 다른 활성 분리 업무는 유지한다.
