        '3번째 이관 초과 업무 비활성 및 다른 활성 업무 유지',
        'Y',
        TO_DATE('2026-07-15 10:00:00', 'YYYY-MM-DD HH24:MI:SS')
    )
    RETURNING COMPLAINT_ID INTO V_COMPLAINT_ID;

    INSERT INTO COMPLAINT_WORK (
        COMPLAINT_ID, PARENT_WORK_ID, DEPT_ID, ACCOUNT_ID,
        STATUS_ID, WORK_SEQUENCE, ENABLED, CREATED_AT, UPDATED_AT
    ) VALUES (
        V_COMPLAINT_ID, NULL, V_WELFARE_DEPT, 111,
        V_PROCESSING_STATUS, 1, 'Y',
        TO_DATE('2026-07-15 10:00:00', 'YYYY-MM-DD HH24:MI:SS'),
        TO_DATE('2026-07-15 10:00:00', 'YYYY-MM-DD HH24:MI:SS')
    )
    RETURNING WORK_ID INTO V_ACTIVE_WORK;

    INSERT INTO COMPLAINT_WORK (
        COMPLAINT_ID,
        PARENT_WORK_ID,
        DEPT_ID,
        ACCOUNT_ID,
        STATUS_ID,
        WORK_RESULT_CODE_ID,
        WORK_SEQUENCE,
        STARTED_AT,
        ENDED_AT,
        ENABLED,
        CREATED_AT,
        UPDATED_AT
    ) VALUES (
