        V_RECEIVED_STATUS,
        V_TRANSFER_RESULT,
        2,
        TO_DATE('2026-07-15 10:00:00', 'YYYY-MM-DD HH24:MI:SS'),
        TO_DATE('2026-07-16 10:00:00', 'YYYY-MM-DD HH24:MI:SS'),
        'N',
        TO_DATE('2026-07-15 10:00:00', 'YYYY-MM-DD HH24:MI:SS'),
        TO_DATE('2026-07-16 10:00:00', 'YYYY-MM-DD HH24:MI:SS')
    )
    RETURNING WORK_ID INTO V_WORK1;

    INSERT INTO COMPLAINT_WORK (
        COMPLAINT_ID,
        PARENT_WORK_ID,
        DEPT_ID,
        ACCOUNT_ID,
        STATUS_ID,
        WORK_RESULT_CODE_ID,
        WORK_SEQUENCE,
        STARTED_AT,
        ENDED_AT,
        ENABLED,
        CREATED_AT,
        UPDATED_AT
    ) VALUES (
        V_COMPLAINT_ID,
        V_WORK1,
