-- 규칙사례 29~34 데이터를 최종 확정한다.
COMMIT;

-- ============================================================================
-- 13. 핵심 업무 규칙 최종 검증
-- ============================================================================
-- 활성 업무가 하나도 없는 민원이 존재하는지 확인한다. 정상 결과는 0건이다.
SELECT C.COMPLAINT_ID,
       C.TITLE,
       SUM(CASE WHEN CW.ENABLED = 'Y' THEN 1 ELSE 0 END) AS ACTIVE_COUNT
  FROM COMPLAINT C
  JOIN COMPLAINT_WORK CW
    ON CW.COMPLAINT_ID = C.COMPLAINT_ID
 GROUP BY C.COMPLAINT_ID, C.TITLE
HAVING SUM(CASE WHEN CW.ENABLED = 'Y' THEN 1 ELSE 0 END) = 0
 ORDER BY C.COMPLAINT_ID;

-- 원본 민원 기준 이관 횟수가 2회를 초과한 데이터가 있는지 확인한다.
SELECT C.COMPLAINT_ID,
       C.TITLE,
       COUNT(ET.EVENT_ID) AS TRANSFER_COUNT
  FROM COMPLAINT C
  JOIN COMPLAINT_WORK CW
    ON CW.COMPLAINT_ID = C.COMPLAINT_ID
  LEFT JOIN PROCESS_EVENT PE
    ON PE.WORK_ID = CW.WORK_ID
  LEFT JOIN EVENT_TRANSFER ET
    ON ET.EVENT_ID = PE.EVENT_ID
 GROUP BY C.COMPLAINT_ID, C.TITLE
HAVING COUNT(ET.EVENT_ID) > 2
 ORDER BY C.COMPLAINT_ID;

-- 일반소관확인 부서에 REJECTED 상태가 남아 있는지 확인한다.
SELECT C.COMPLAINT_ID,
       C.TITLE,
       CW.WORK_ID,
       S.STATUS_CODE,
       CW.ENABLED
  FROM COMPLAINT_WORK CW
  JOIN COMPLAINT C
    ON C.COMPLAINT_ID = CW.COMPLAINT_ID
  JOIN DEPARTMENT D
    ON D.DEPT_ID = CW.DEPT_ID
  JOIN STATUS S
    ON S.STATUS_ID = CW.STATUS_ID
 WHERE D.DEPT_CODE = 'GENERAL_REVIEW'
   AND S.STATUS_CODE = 'REJECTED';

-- 규칙사례별 업무 순서, 담당 부서, 상태, 활성 여부와 부모 업무를 확인한다.
SELECT C.TITLE,
       CW.WORK_SEQUENCE,
       D.DEPT_NAME,
       S.STATUS_CODE,
       CW.ENABLED,
       CW.PARENT_WORK_ID,
       CW.ENDED_AT
  FROM COMPLAINT C
  JOIN COMPLAINT_WORK CW
    ON CW.COMPLAINT_ID = C.COMPLAINT_ID
  JOIN DEPARTMENT D
    ON D.DEPT_ID = CW.DEPT_ID
  JOIN STATUS S
    ON S.STATUS_ID = CW.STATUS_ID
 WHERE C.TITLE LIKE '[규칙사례%'
 ORDER BY C.COMPLAINT_ID, CW.WORK_SEQUENCE;

-- 각 규칙사례의 실제 부서 이관 횟수를 확인한다.
SELECT C.TITLE,
       COUNT(ET.EVENT_ID) AS TRANSFER_COUNT
  FROM COMPLAINT C
  JOIN COMPLAINT_WORK CW
    ON CW.COMPLAINT_ID = C.COMPLAINT_ID
  LEFT JOIN PROCESS_EVENT PE
    ON PE.WORK_ID = CW.WORK_ID
  LEFT JOIN EVENT_TRANSFER ET
    ON ET.EVENT_ID = PE.EVENT_ID
 WHERE C.TITLE LIKE '[규칙사례%'
 GROUP BY C.COMPLAINT_ID, C.TITLE
 ORDER BY C.COMPLAINT_ID;



















